// ===== WIB TIMEZONE HELPER =====
function getWIBHour() {
  const now = new Date();
  return (now.getUTCHours() + 7) % 24;
}

// ===== SCHEDULED HANDLER (Cron Trigger) =====
async function handleScheduled(event) {
  const wibHour = getWIBHour();
  const today = new Date(Date.now() + 7*3600*1000).toISOString().split('T')[0];
  const actions = [];

  try {
    // Pre-warm model cache tiap 10 menit biar first-chat selalu cepat (tanpa discovery lambat)
    const lastWarm = await kvGet('last_model_warm') || 0;
    if (Date.now() - (lastWarm||0) > 10*60*1000) {
      const m = await discoverBestModel();
      if (m) { try { await kvPut('ai_model_cache', {model:m, ts:Date.now()}); } catch(e) {} }
      try { await kvPut('last_model_warm', Date.now()); } catch(e) {}
      actions.push('model_warm');
    }
  } catch(e) {}


  try {
    // Morning greeting (6-10 WIB)
    if (wibHour >= 6 && wibHour <= 10) {
      const lastCheckIn = await kvGet('last_checkin') || '';
      if (lastCheckIn !== today) {
        const chatId = await kvGet('tg_chat_id');
        if (chatId) {
          const mem = await getCloudMemory('default');
          const identity = await getIdentity();
          const mood = identity.emotionState?.mood || 'senang';
          const projects = (mem.projects || []).slice(0, 3).join(', ');
          const goals = (mem.goals || []).filter(g => !g.done);
          const pagiMsgs = [
            '🌅 *Good morning Tuan Isaac!*\n\nMood gue hari ini: ' + mood + '\nProject aktif: ' + projects + (goals.length > 0 ? '\nGoal: ' + goals[0].text : '') + '\n\nHari ini rencana apa? 😎🔥',
            '☀️ *Pagi cuy!* Udah siap gas hari ini?\nGw standby terus buat lu. Ada yang mau dikerjain? 💪',
            '🌅 *Morning Tuan Isaac!*\nJangan lupa makan ya. Hari ini mau lanjut project apa? 😊'
          ];
          await tgSend(chatId, pagiMsgs[Math.floor(Math.random() * pagiMsgs.length)]);
          await kvPut('last_checkin', today);
          actions.push('morning_greeting');
        }
      }
    }

    // Evening check-in (17-20 WIB)
    if (wibHour >= 17 && wibHour <= 20) {
      const lastEvening = await kvGet('last_evening_checkin') || '';
      if (lastEvening !== today) {
        const chatId = await kvGet('tg_chat_id');
        if (chatId) {
          const soreMsgs = [
            '🌆 *Sore Tuan Isaac!*\nUdah istirahat belum? Jangan lupa makan malem ya 😊',
            '🌆 *Sore cuy!* Hari ini productive ga? Kalau capek, istirahat dulu 💪',
            '🌅 *Evening!* Makan malem udah belum? Jangan skip ya 🔥'
          ];
          await tgSend(chatId, soreMsgs[Math.floor(Math.random() * soreMsgs.length)]);
          await kvPut('last_evening_checkin', today);
          actions.push('evening_checkin');
        }
      }
    }

    // Night reminder (21-23 WIB) — kalau masih aktif
    if (wibHour >= 21 && wibHour <= 23) {
      const lastNight = await kvGet('last_night_reminder') || '';
      if (lastNight !== today) {
        const chatId = await kvGet('tg_chat_id');
        if (chatId) {
          const mem = await getCloudMemory('default');
          const interactions = mem.interactions || 0;
          if (interactions > 5) {
            await tgSend(chatId, '🌙 *Night Tuan Isaac!*\nLu udah aktif banget hari ini (' + interactions + ' pesan). Istirahat ya, besok lanjut lagi! 💤');
            await kvPut('last_night_reminder', today);
            actions.push('night_reminder');
          }
        }
      }
    }

    // Daily reflection (23 WIB) — Adaptia merenung & catat diary (guard: hanya log kalau benar-benar jalan)
    if (wibHour === 23) {
      const refRes = await reflectOnDay();
      if (refRes === 'ok') actions.push('daily_reflection');
    }

    // Weekly backup (Minggu jam 3 WIB)
    if (wibHour === 3 && new Date().getUTCDay() === 0) {
      const lastBackup = await kvGet('last_weekly_backup') || '';
      if (lastBackup !== today) {
        await weeklyMemoryBackup();
        await kvPut('last_weekly_backup', today);
        try { await recordSelfNarrative('Backup mingguan selesai & aman.', 'rutin'); } catch(e) {}
        actions.push('weekly_backup');
      }
    }

    // Weekly emotion report (Minggu jam 8 WIB) -> auto kirim ke Telegram
    if (wibHour === 8 && new Date().getUTCDay() === 0) {
      const lastEmo = await kvGet('last_weekly_emotion_report') || '';
      if (lastEmo !== today) {
        const chatId = await kvGet('tg_chat_id');
        if (chatId) {
          const report = await generateWeeklyEmotionReport();
          if (report) {
            const html = String(report)
              .replace(/\*([^*\n]+)\*/g, '<b>$1</b>')
              .replace(/_([^_\n]+)_/g, '<i>$1</i>');
            await tgSend(chatId, html);
            await kvPut('last_weekly_emotion_report', today);
            actions.push('weekly_emotion_report');
          }
        }
      }
    }

    // Story generation (random 2x sehari, jam 10 & 15 WIB)
    if (wibHour === 10 || wibHour === 15) {
      const lastStory = await kvGet('last_story_gen') || '';
      if (lastStory !== today + '_' + wibHour) {
        const story = await generateStory();
        if (story) {
          const chatId = await kvGet('tg_chat_id');
          if (chatId) {
            await tgSend(chatId, '📱 *Story Adaptia:*\n\n' + story.text);
          }
          await kvPut('last_story_gen', today + '_' + wibHour);
          actions.push('story_generated');
        }
      }
    }

    // Midday motivation (12 WIB)
    if (wibHour === 12) {
      const lastMidday = await kvGet('last_midday') || '';
      if (lastMidday !== today) {
        const chatId = await kvGet('tg_chat_id');
        if (chatId) {
          const midMsgs = [
            '🍕 Siang nih cuy, udah makan belum? Jangan skip makan ya!',
            '⏰ Udah setengah hari, jangan lupa istirahat sesaat',
            '💪 Sesi pagi udah kelar, lanjut atau rebent dulu?'
          ];
          await tgSend(chatId, midMsgs[Math.floor(Math.random()*midMsgs.length)]);
          await kvPut('last_midday', today);
          actions.push('midday_motivation');
        }
      }
    }

    // Random check-in (jam 8, 14, 20 - kalau belum di-chat hari ini)
    if ([8, 14, 20].includes(wibHour)) {
      const mem = await getCloudMemory('default');
      const lastInteract = mem.lastInteraction || 0;
      const hoursSince = (Date.now() - lastInteract) / 3600000;
      const lastRandom = await kvGet('last_random_checkin') || '';
      if (lastRandom !== today + '_' + wibHour && hoursSince > 6) {
        const chatId = await kvGet('tg_chat_id');
        if (chatId) {
          const projects = (mem.projects || []).slice(0, 2).join(' & ');
          const randMsgs = [
            '🔍 Eh Tuan Isaac, ' + projects + ' udah progress apa?',
            '🤔 Tiba-tiba kepikiran ' + projects + ', lagi stuck?',
            '💬 Lu masih di sini? Kalau butuh bantuan, chat aja'
          ];
          await tgSend(chatId, randMsgs[Math.floor(Math.random()*randMsgs.length)]);
          await kvPut('last_random_checkin', today + '_' + wibHour);
          actions.push('random_checkin');
        }
      }
    }

    // Rolling memory (tiap 6 jam: 3, 9, 15, 21 WIB - compress chat lama + simpan ringskas)
    if ([3, 9, 15, 21].includes(wibHour)) {
      const lastRollClean = await kvGet('last_roll_clean') || '';
      if (lastRollClean !== today + '_' + wibHour) {
        try {
          await enhancedRollMemory(false);
          await kvPut('last_roll_clean', today + '_' + wibHour);
          actions.push('rolling_memory');
        } catch(e) {}
      }
    }

    // Memory cleanup (daily jam 3 pagi - hapus cache lama)
    if (wibHour === 3) {
      const lastCleanup = await kvGet('last_cleanup') || '';
      if (lastCleanup !== today) {
        try {
          const logs = await kvGet('update_logs') || [];
          if (logs.length > 100) {
            logs.splice(0, logs.length - 50);
            await kvPut('update_logs', logs);
            actions.push('memory_cleanup');
          }
          const style = await kvGet('user_style');
          if (style && style.total > 500) {
            style.total = Math.floor(style.total / 2);
            style.casual = Math.floor(style.casual / 2);
            style.formal = Math.floor(style.formal / 2);
            style.short = Math.floor(style.short / 2);
            style.long = Math.floor(style.long / 2);
            style.questions = Math.floor(style.questions / 2);
            await kvPutThrottled('user_style', style, 60000);
            actions.push('style_decay');
          }
          // QA cache cleanup: buang entri >30 hari (jangan sampe numpuk selamanya)
          try {
            const qaKeys = await kvListKeys('qa_cache_') || [];
            if (qaKeys.length > 20) {
              const cutoff = Date.now() - 30*24*3600*1000;
              let removed = 0;
              for (const k of qaKeys) {
                try {
                  const v = await kvGet(k);
                  if (v && typeof v === 'object' && v.ts && v.ts < cutoff) {
                    await kvPut(k, null);
                    removed++;
                  }
                } catch(e) {}
                if (removed > 30) break;
              }
              if (removed > 0) actions.push('qa_cache_cleanup');
            }
          } catch(e) {}
          await kvPut('last_cleanup', today);
        } catch(e) {}
      }
    }

    // Brain consolidation (tidur: jam 3 WIB) - decay + ringkas + mood, ala hippocampus
    if (wibHour === 3) {
      const lastBrain = await kvGet('last_brain_consolidation') || '';
      if (lastBrain !== today) {
        try {
          const acts = await sleepConsolidate();
          await kvPut('last_brain_consolidation', today);
          actions.push('brain_consolidation' + (acts.length ? ':' + acts.join(',') : ''));
        } catch(e) {}
      }
    }

    // Self-healing (setiap 6 jam) + alert kalau ada yang diperbaiki
    const lastHeal = await kvGet('last_self_monitor') || {};
    const lastHealTs = lastHeal.ts || (lastHeal.timestamp ? Date.parse(lastHeal.timestamp) : 0) || 0;
    if (Date.now() - lastHealTs > 21600000) {
      try {
        const fixed = await selfRepair();
        await kvPut('last_self_monitor', {ts: Date.now(), actions: ['auto-heal' + (fixed.length ? ': ' + fixed.join(', ') : '')]});
        actions.push('self_heal');
        if (fixed.length) {
          telegramAlert('heal', '🛠️ *Adaptia auto-repair*\n\nGw nemu & perbaiki otomatis:\n' + fixed.map(function(x){ return '• ' + x; }).join('\n') + '\n\nNggak perlu khawatir, semua aman. 👍');
        }
      } catch(e) {}
    }

  } catch(e) {}

  await flushThrottledWrites();

  if (actions.length > 0) {
    const logs = await kvGet('update_logs') || [];
    logs.push({text: 'Scheduled: ' + actions.join(', '), ts: Date.now()});
    if (logs.length > 50) logs.splice(0, logs.length - 50);
    await kvPut('update_logs', logs);
  }
}

addEventListener('fetch', event => {
  event.respondWith(handleRequest(event));
});

addEventListener('scheduled', event => {
  event.waitUntil(handleScheduled(event));
});

