async function kvGet(key) {
  // Prefer native KV binding (fast, no REST API rate limits)
  let bindingOk = true;
  try {
    if (typeof MEMORY_KV !== 'undefined' && MEMORY_KV) {
      const v = await MEMORY_KV.get(key);
      if (v !== null && v !== undefined) {
        try { return JSON.parse(v); } catch(e) { return v; }
      }
      // v null -> key kosong; binding mendefinisikan kebenaran, langsung ke fallback di bawah
    }
  } catch(e) { bindingOk = false; }
  if (!bindingOk) {
    try {
      const r = await fetch(API_BASE + '/' + encodeURIComponent(key), {headers:{'Authorization':'Bearer '+CF_TOKEN}});
      if (r.ok) {
        try { return JSON.parse(await r.text()); } catch(e) { return await r.text(); }
      }
    } catch(e) {}
  }
  // Fallback: learning seed embedded (dipakai kalau KV kosong / quota write habis)
  if (typeof LEARNING_SEED !== 'undefined' && LEARNING_SEED && Object.prototype.hasOwnProperty.call(LEARNING_SEED, key)) {
    try { return JSON.parse(JSON.stringify(LEARNING_SEED[key])); } catch(e) {}
  }
  return null;
}
// ===== RATE LIMITER =====
const rateLimitMap = new Map();
function checkRateLimit(ip, maxReq, windowMs) {
  const now = Date.now();
  const key = ip;
  const data = rateLimitMap.get(key) || {count:0, reset:now+windowMs};
  if(now > data.reset) { data.count = 0; data.reset = now + windowMs; }
  data.count++;
  rateLimitMap.set(key, data);
  return data.count <= maxReq;
}
function isRateLimited(ip) {
  return !checkRateLimit(ip, 30, 60000);
}
// ===== INPUT SANITIZER =====
function sanitize(input) {
  if(typeof input !== "string") return "";
  return input.replace(/<[^>]*>/g, "").replace(/javascript:/gi, "").replace(/on\w+=/gi, "").replace(/script/gi, "").substring(0, 2000);
}
function isValidInput(input) {
  if(!input || typeof input !== "string") return false;
  if(input.length < 1 || input.length > 2000) return false;
  if(input.match(/<script/i) || input.match(/javascript:/i) || input.match(/on\w+\s*=/i)) return false;
  return true;
}
function isLoginLimited(ip) {
  return !checkRateLimit(ip, 5, 3600000);
}
async function kvListKeys(prefix) {
  try {
    if (typeof MEMORY_KV !== 'undefined' && MEMORY_KV && MEMORY_KV.list) {
      const names = [];
      let cursor = undefined;
      do {
        const res = await MEMORY_KV.list({prefix: prefix || '', cursor: cursor, limit: 1000});
        (res.keys || []).forEach(function(k){ names.push(k.name); });
        cursor = res.cursor;
      } while (cursor);
      return names;
    }
  } catch(e) {}
  try {
    const names = [];
    let cursor = undefined;
    do {
      const url = API_BASE + '?prefix=' + encodeURIComponent(prefix || '') + '&limit=1000' + (cursor ? '&cursor=' + encodeURIComponent(cursor) : '');
      const r = await fetch(url, {headers:{'Authorization':'Bearer '+CF_TOKEN}});
      const d = await r.json();
      (d.result || []).forEach(function(k){ names.push(k.name); });
      cursor = d.result_info && d.result_info.cursor;
    } while (cursor);
    return names;
  } catch(e) { return null; }
}

async function kvPut(key, val) {
  const body = typeof val === 'string' ? val : JSON.stringify(val);
  // Prefer native KV binding (fast, no REST API rate limits)
  try {
    if (typeof MEMORY_KV !== 'undefined' && MEMORY_KV) {
      await MEMORY_KV.put(key, body);
      return;
    }
  } catch(e) {}
  // Fallback: REST API with 1 retry on transient failure
  for(let attempt = 0; attempt < 2; attempt++){
    try {
      const r = await fetch(API_BASE + '/' + encodeURIComponent(key), {method:'PUT',headers:{'Authorization':'Bearer '+CF_TOKEN,'Content-Type':'application/json'},body});
      if(r.ok || r.status < 500) return;
    } catch(e) {}
  }
}

// === WRITE THROTTLE: hemat kuota KV harian (nilai terbaru menang) ===
const throttleWriteMap = new Map();
const throttlePending = new Map();
async function kvPutThrottled(key, val, minMs) {
  try {
    const now = Date.now();
    const min = minMs || 60000;
    const last = throttleWriteMap.get(key);
    throttlePending.set(key, val);
    if (last === undefined || now - last >= min) {
      throttleWriteMap.set(key, now);
      throttlePending.delete(key);
      await kvPut(key, val);
    }
  } catch(e) {}
}
async function flushThrottledWrites() {
  try {
    if (!throttlePending.size) return;
    const items = Array.from(throttlePending.entries());
    throttlePending.clear();
    for (let i = 0; i < items.length; i++) {
      try { await kvPut(items[i][0], items[i][1]); } catch(e) {}
    }
  } catch(e) {}
}

