async function learnFactBatch(userId, facts, insights) {
  const mem = await getCloudMemory(userId);
  if (!mem.facts) mem.facts = [];
  if (!mem.insights) mem.insights = [];
  const addOne = function(arr, item, cap){
    const clean = String(item || '').trim().replace(/\s+/g, ' ');
    if (clean.length <= 5) return;
    const lower = clean.toLowerCase();
    const words = function(s){ return String(s).toLowerCase().replace(/[^a-z0-9\s]/g,' ').split(/\s+/).filter(function(w){ return w.length > 2; }); };
    const overlap = function(a, b){
      const A = words(a), B = words(b);
      if(!A.length || !B.length) return 0;
      let inter = 0;
      const Bs = {};
      B.forEach(function(w){ Bs[w] = true; });
      A.forEach(function(w){ if(Bs[w]) inter++; });
      return inter / Math.min(A.length, B.length);
    };
    if (arr.some(function(f){ return f && String(f).trim().replace(/\s+/g,' ').toLowerCase() === lower; })) return;
    if (arr.some(function(f){ return f && overlap(f, clean) > 0.65; })) return;
    arr.push(clean.substring(0, 200));
    if (arr.length > cap) arr.splice(0, arr.length - cap);
  };
  (facts || []).forEach(function(f){ addOne(mem.facts, f, 60); });
  (insights || []).forEach(function(i){ if(i && String(i).trim().length >= 8) addOne(mem.insights, i, 24); });
  if (!(facts||[]).length && !(insights||[]).length) return;
  mem.lastSeen = new Date().toISOString();
  await kvPut('mem_' + (userId || 'default'), mem);
}

async function learnFact(userId, fact) {
  await learnFactBatch(userId, [fact], []);
}

async function learnInsight(userId, insight) {
  await learnFactBatch(userId, [], [insight]);
}



// === LEARNING UPGRADE: Feedback Loop + Topic Mastery + Response Quality ===
async function recordFeedback(rating, topic, responseSnippet){
  try{
    const fb = await kvGet('feedback_log') || [];
    fb.push({ rating: Math.max(1,Math.min(5,rating)), topic: topic||'umum', snippet: String(responseSnippet||'').substring(0,120), ts: Date.now() });
    try {
      if (rating >= 5) await recordSelfNarrative('Tuan puas banget sama jawaban gw (topik ' + (topic||'umum') + ') — jadi bahan buat gw pertahanin. ' + Date.now(), 'umpan');
      else if (rating <= 2) await recordSelfNarrative('Tuan kurang puas di topik ' + (topic||'umum') + ' — gw catet buat mendingin ke depannya.', 'umpan');
    } catch(e) {}
    if(fb.length > 200) fb.splice(0, fb.length - 200);
    await kvPut('feedback_log', fb);
    // Update topic mastery
    const mastery = await kvGet('topic_mastery') || {};
    const t = topic || 'umum';
    if(!mastery[t]) mastery[t] = {good:0,bad:0,total:0};
    mastery[t].total++;
    if(rating >= 4) mastery[t].good++;
    else if(rating <= 2) mastery[t].bad++;
    await kvPut('topic_mastery', mastery);
  }catch(e){}
}

async function getTopicMastery(topic){
  try{
    const mastery = await kvGet('topic_mastery') || {};
    const m = mastery[topic] || mastery['umum'] || {good:0,bad:0,total:0};
    const score = m.total > 0 ? Math.round((m.good / m.total) * 100) : 50;
    return { topic, score, good: m.good, bad: m.bad, total: m.total };
  }catch(e){ return { topic, score: 50, good:0, bad:0, total:0 }; }
}

async function getLearningStats(){
  try{
    const fb = await kvGet('feedback_log') || [];
    const mastery = await kvGet('topic_mastery') || {};
    const recent = fb.slice(-20);
    const avgRating = recent.length > 0 ? (recent.reduce((a,f)=>a+f.rating,0) / recent.length).toFixed(1) : 0;
    const topTopics = Object.entries(mastery).sort((a,b)=>(b[1].good/(b[1].total||1))-(a[1].good/(a[1].total||1))).slice(0,5);
    const weakTopics = Object.entries(mastery).filter(([,v])=>v.bad > v.good && v.total > 2).map(([k])=>k);
    return { avgRating, totalFeedback: fb.length, topTopics, weakTopics, topicCount: Object.keys(mastery).length };
  }catch(e){ return { avgRating:0, totalFeedback:0, topTopics:[], weakTopics:[], topicCount:0 }; }
}

