// ===== KNOWLEDGE BASE =====
async function searchKnowledge(query) {
  try{
    const data = await kvGet('knowledge_base');
    if (!data || !Array.isArray(data)) return [];
    const q = String(query||'').toLowerCase().replace(/[^a-z0-9\s]/g,' ').trim();
    const tokens = q.split(/\s+/).filter(function(t){ return t.length >= 3; });
    if (!q && tokens.length === 0) return [];
    const scored = [];
    for (const k of data) {
      if (!k || !k.title) continue;
      const title = (k.title||'').toLowerCase();
      const content = (k.content||'').toLowerCase();
      const tags = (k.tags||[]).map(t => (t||'').toLowerCase());
      let score = 0;
      if (q && (title === q || title.startsWith(q) || title.includes(q))) score += 50;
      if (q && content.includes(q)) score += 30;
      if (q && tags.some(t => t === q || t.startsWith(q))) score += 25;
      for (const t of tokens) {
        if (title.includes(t)) score += 4;
        if (content.includes(t)) score += 2;
        if (tags.some(tag => tag.includes(t))) score += 1;
      }
      if (score > 0) scored.push({k, score});
    }
    scored.sort((a,b) => b.score - a.score);
    return scored.slice(0, 4).map(x => x.k);
  }catch(e){ return []; }
}

async function addKnowledge(title, content, tags) {
  const data = (await kvGet('knowledge_base')) || [];
  data.push({title, content, tags: tags||[], created: new Date().toISOString()});
  if (data.length > 200) data.splice(0, data.length - 200);
  await kvPut('knowledge_base', data);
}


// ===== RAG MEMORY SYSTEM =====
// Uses CF Workers AI bge-m3 embedding + cosine similarity for semantic memory
// Lives entirely in KV — no external vector DB needed

function ragPackF32(arr){
  const f32 = new Float32Array(arr);
  const bytes = new Uint8Array(f32.buffer);
  let s = '';
  for(let i=0;i<bytes.length;i++) s += String.fromCharCode(bytes[i]);
  return btoa(s);
}
function ragUnpackF32(b64){
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for(let i=0;i<bin.length;i++) bytes[i] = bin.charCodeAt(i);
  return new Float32Array(bytes.buffer);
}
function ragCosine(a,b){
  let dot=0, na=0, nb=0;
  for(let i=0;i<a.length;i++){dot+=a[i]*b[i];na+=a[i]*a[i];nb+=b[i]*b[i];}
  return dot/(Math.sqrt(na)*Math.sqrt(nb)||1);
}

const RAG_MAX = 400;

async function ragEmbed(text){
  try{
    const r = await fetch('https://api.cloudflare.com/client/v4/accounts/'+CF_ACCOUNT_ID+'/ai/run/@cf/baai/bge-m3',{
      method:'POST',headers:{'Authorization':'Bearer '+CF_AI_TOKEN,'Content-Type':'application/json'},
      body:JSON.stringify({text:[String(text||'').substring(0,800)]})
    });
    const d = await r.json();
    if(d.result && d.result.data && d.result.data[0]) return d.result.data[0];
  }catch(e){}
  return null;
}

async function ragSearch(query, topK){
  topK = topK||4;
  try{
    const qEmb = await ragEmbed(query);
    if(!qEmb) return '';
    const memories = await kvGet('rag_memories') || [];
    if(!memories.length) return '';
    const scored = [];
    for(const m of memories){
      try{
        const mEmb = m.emb ? ragUnpackF32(m.emb) : null;
        if(!mEmb || mEmb.length !== qEmb.length) continue;
        const sim = ragCosine(qEmb, mEmb);
        if(sim > 0.35) scored.push({t:m.t, s:sim});
      }catch(e){}
    }
    scored.sort((a,b)=>b.s-a.s);
    return scored.slice(0,topK).map(x=>'['+Math.round(x.s*100)+'%] '+x.t).join('\n');
  }catch(e){return '';}
}

async function ragRemember(userText, botText){
  try{
    const combined = (userText||'').substring(0,400)+' | '+((botText||'').substring(0,400));
    if(combined.length < 20) return;
    const emb = await ragEmbed(combined);
    if(!emb) return;
    const memories = await kvGet('rag_memories') || [];
    // Dedupe: skip if very similar text exists (first 80 chars)
    const prefix = combined.substring(0,80).toLowerCase();
    const exists = memories.some(m => (m.t||'').substring(0,80).toLowerCase() === prefix);
    if(exists) return;
    memories.push({t:combined, emb:ragPackF32(emb), ts:Date.now()});
    if(memories.length > RAG_MAX) memories.splice(0, memories.length - RAG_MAX);
    await kvPut('rag_memories', memories);
  }catch(e){}
}


