const PIN_PATTERNS = [
  /(gw|aku|saya|gue|elu|lu)\s+(lahir|kerja|tinggal|punya|suka|hobi|pengen|mau)\b/i,
  /(tanggal lahir|ulang tahun|nama gw|nama aku|nama saya|kerja di|tinggal di|sahabat|istri|pacar|ibu|bapak|kakak|adik|keluarga)\b/i,
  /(mdc|bekasi|virgo|perfectionis|teliti|hafizh|icha|pijay|prissil|grezio|iknas)\b/i
];

function scoreImportance(text, entities){
  let imp = 4;
  const low = ' ' + String(text||'').toLowerCase() + ' ';
  if(/!+/.test(text)) imp += 1;
  if(/(penting|serius|jangan lupa|inget|tolong|wajib|harus)/.test(low)) imp += 2;
  if(/ (gw|aku|saya|gue)\s+(lahir|kerja|tinggal|lulus|punya|suka|gak suka|ingin|pengen|mau|target|impian|harapan) /.test(low)) imp += 3;
  if(/(stres|sedih|senang|happy|capek|ngantuk|galau|marah|kesel|mood)/.test(low)) imp += 1;
  if(String(text||'').length > 120) imp += 1;
  if(entities && entities.length) imp += Math.min(2, entities.length);
  if(/\?\s*$/.test(String(text||'').trim())) imp -= 1;
  return Math.max(1, Math.min(10, imp));
}

function isPinnedMemory(text){
  const low = String(text||'').toLowerCase();
  for(let i=0;i<PIN_PATTERNS.length;i++){ if(PIN_PATTERNS[i].test(low)) return true; }
  return false;
}

function levelConfidence(text){
  const low = String(text||'').toLowerCase();
  if(/(mungkin|kayaknya|entah|gatau|gue gatau|tapi|rasanya)/.test(low)) return 'ragu';
  return 'yakin';
}

// Entitas yang dikenali: orang/tempat/project penting Tuan Isaac
const MEMORY_ENTITIES = {
  'pak grezio': ['kerja'],
  'grezio': ['kerja'],
  'iknas': ['kerja'],
  'hafizh': ['pertemanan'],
  'icha': ['pertemanan'],
  'pijay': ['pertemanan'],
  'prissil': ['pertemanan'],
  'bunda rahma': ['pertemanan'],
  'tuan isaac': ['pribadi'],
  'mdc': ['kerja','tempat'],
  'bekasi': ['pribadi','tempat'],
  'adaptia': ['proyek'],
  'madara': ['proyek'],
  'office boy': ['kerja']
};

function classifyMemoryTopics(text){
  const low = ' ' + String(text||'').toLowerCase() + ' ';
  const hits = [];
  for(let i=0;i<MEMORY_TOPICS.length;i++){
    const t = MEMORY_TOPICS[i];
    let matched = 0;
    for(let k=0;k<t.keywords.length;k++){
      const kw = t.keywords[k].toLowerCase();
      if(kw.length > 2 && low.indexOf(kw) !== -1) matched++;
    }
    if(matched > 0) hits.push({topic:t.topic, score:matched});
  }
  hits.sort(function(a,b){ return b.score - a.score; });
  return hits.map(function(h){ return h.topic; });
}

function escapeRe(str){
  return String(str).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function extractMemoryEntities(text){
  const low = ' ' + String(text||'').toLowerCase() + ' ';
  const found = [];
  const keys = Object.keys(MEMORY_ENTITIES);
  for(let i=0;i<keys.length;i++){
    const k = keys[i];
    const re = new RegExp('(^|[^a-z0-9])' + escapeRe(k) + '($|[^a-z0-9])');
    if(re.test(low) && found.indexOf(k) === -1) found.push(k);
  }
  // Pola generik panggilan: pak/bu/kak/bang/om/tante + nama (min 3 huruf)
  const generic = /(?:^|[^a-z0-9])(pak|bu|kak|bang|om|tante)\s+([a-z]{3,})/g;
  let m;
  while((m = generic.exec(low)) !== null){
    const name = m[1] + ' ' + m[2];
    if(found.indexOf(name) === -1) found.push(name);
  }
  return found;
}

