// --- DEDUP UPGRADE: TF-IDF Scoring + Semantic Similarity ---
// Build IDF cache from all stored memories
async function buildIDFCache(){
  try{
    const idx = await memoryIndexGet();
    const docFreq = {};
    let totalDocs = 0;
    for(let e=0; e<idx.length; e++){
      const items = idx[e].items || [];
      for(let i=0; i<items.length; i++){
        const words = String(items[i].t||'').toLowerCase().replace(/[^a-z0-9\s]/g,' ').split(/\s+/).filter(function(x){return x.length>2;});
        const unique = {};
        words.forEach(function(w){ unique[w] = true; });
        Object.keys(unique).forEach(function(w){ docFreq[w] = (docFreq[w]||0) + 1; });
        totalDocs++;
      }
    }
    // Calculate IDF for each word
    const idf = {};
    for(var w in docFreq){
      idf[w] = Math.log((totalDocs + 1) / (docFreq[w] + 1)) + 1;
    }
    return {idf: idf, totalDocs: totalDocs};
  }catch(e){ return {idf:{}, totalDocs:0}; }
}

// TF-IDF weighted similarity
function tfidfSimilarity(a, b, idfCache){
  try{
    const wa = String(a||'').toLowerCase().replace(/[^a-z0-9\s]/g,' ').split(/\s+/).filter(function(x){return x.length>2;});
    const wb = String(b||'').toLowerCase().replace(/[^a-z0-9\s]/g,' ').split(/\s+/).filter(function(x){return x.length>2;});
    if(!wa.length || !wb.length) return 0;
    const idf = (idfCache && idfCache.idf) || {};
    // TF for each doc
    const tfA = {};
    wa.forEach(function(w){ tfA[w] = (tfA[w]||0) + 1; });
    const tfB = {};
    wb.forEach(function(w){ tfB[w] = (tfB[w]||0) + 1; });
    // TF-IDF vectors
    const vecA = {};
    wa.forEach(function(w){ vecA[w] = (tfA[w] / wa.length) * (idf[w] || 1); });
    const vecB = {};
    wb.forEach(function(w){ vecB[w] = (tfB[w] / wb.length) * (idf[w] || 1); });
    // Cosine similarity
    let dot = 0, normA = 0, normB = 0;
    var allWords = {};
    wa.forEach(function(w){ allWords[w] = true; });
    wb.forEach(function(w){ allWords[w] = true; });
    for(var w in allWords){
      var a = vecA[w] || 0;
      var b = vecB[w] || 0;
      dot += a * b;
      normA += a * a;
      normB += b * b;
    }
    return dot / (Math.sqrt(normA) * Math.sqrt(normB) || 1);
  }catch(e){ return 0; }
}

// Combined similarity: 60% TF-IDF + 40% basic overlap (for backward compatibility)
function memSimilarity(a, b){
  try{
    // Basic word overlap
    const wa = String(a||'').toLowerCase().replace(/[^a-z0-9\s]/g,' ').split(/\s+/).filter(function(x){return x.length>2;});
    const wb = String(b||'').toLowerCase().replace(/[^a-z0-9\s]/g,' ').split(/\s+/).filter(function(x){return x.length>2;});
    if(!wa.length || !wb.length) return 0;
    const setB = {};
    wb.forEach(function(x){ setB[x]=true; });
    let hit = 0; const seen = {};
    wa.forEach(function(x){ if(setB[x] && !seen[x]){ hit++; seen[x]=true; } });
    const overlap = hit / Math.max(wa.length, wb.length);
    // TF-IDF (sync cache)
    const tfidfScore = memSimilarity._tfidfCache ? tfidfSimilarity(a, b, memSimilarity._tfidfCache) : overlap;
    return 0.5 * overlap + 0.5 * tfidfScore;
  }catch(e){ return 0; }
}
memSimilarity._tfidfCache = null;
async function refreshDedupCache(){ memSimilarity._tfidfCache = await buildIDFCache(); }
const MEM_DUP_SIM = 0.55;

async function rememberTopicMemory(userText, mood){
  try{
    const text = String(userText||'').trim();
    if(text.length < 8) return;
    const topics = classifyMemoryTopics(text);
    const entities = extractMemoryEntities(text);
    if(!topics.length && !entities.length) return;
    const now = Date.now();
    const imp = scoreImportance(text, entities);
    const pinned = isPinnedMemory(text);
    const item = { t: text.substring(0, 180), ts: now, e: entities, imp: imp, str: pinned ? 1 : (0.5 + imp*0.05), conf: levelConfidence(text), mood: mood || 'umum', pinned: pinned ? 1 : 0 };
    // 1) Index topik (+ reinforcement kalau pesan/topik sering diulang)
    if(topics.length){
      const idx = await memoryIndexGet();
      let changed = false;
      for(let ti=0; ti<topics.length; ti++){
        let entry = null;
        for(let e=0;e<idx.length;e++){ if(idx[e].topic === topics[ti]){ entry = idx[e]; break; } }
        if(!entry){
          if(idx.length >= MEMORY_TOPIC_MAX_TOPICS) continue;
          entry = { topic: topics[ti], items: [], str: 0.5 };
          idx.push(entry);
        }
        const prefix = item.t.substring(0,60).toLowerCase();
        let dupItem = null;
        for(let ii=0;ii<(entry.items||[]).length;ii++){ const it=entry.items[ii]; if(String(it.t||'').substring(0,60).toLowerCase()===prefix){ dupItem=it; break; } }
        if(dupItem){
          dupItem.str = Math.min(1, (dupItem.str != null ? dupItem.str : 0.6) + 0.1);
          dupItem.ts = now;
          dupItem.imp = Math.max(dupItem.imp || imp, imp);
          entry.active = now;
          entry.str = Math.min(1, (entry.str != null ? entry.str : 0.5) + 0.03);
          changed = true;
          continue;
        }
        // Fuzzy dedup: kalau mirip > 55% -> reinforce, bukan duplikat baru
        let bestSim = 0, bestSimItem = null;
        for(let fi=0;fi<(entry.items||[]).length;fi++){
          const sim = memSimilarity(item.t, entry.items[fi].t);
          if(sim > bestSim){ bestSim = sim; bestSimItem = entry.items[fi]; }
        }
        if(bestSimItem && bestSim >= MEM_DUP_SIM){
          bestSimItem.str = Math.min(1, (bestSimItem.str != null ? bestSimItem.str : 0.6) + 0.12);
          bestSimItem.ts = now;
          bestSimItem.imp = Math.max(bestSimItem.imp || imp, imp);
          entry.active = now;
          entry.str = Math.min(1, (entry.str != null ? entry.str : 0.5) + 0.03);
          changed = true;
          continue;
        }
        entry.items.push(item);
        if(entry.items.length > MEMORY_TOPIC_MAX_PER) entry.items.splice(0, entry.items.length - MEMORY_TOPIC_MAX_PER);
        entry.active = now;
        entry.str = Math.min(1, (entry.str != null ? entry.str : 0.5) + 0.03);
        changed = true;
      }
      if(changed) await kvPut('memory_index', idx);
    }
    // 2) Index entitas + tetangga
    if(entities.length){
      try{
        const ents = await memoryEntitiesGet();
        const top0 = topics[0] || 'umum';
        let ech = false;
        for(let i=0;i<entities.length;i++){
          const en = entities[i];
          let rec = null;
          for(let e=0;e<ents.length;e++){ if(ents[e].e === en){ rec = ents[e]; break; } }
          if(!rec){ rec = { e:en, facts:[], neighbors:[] }; ents.push(rec); }
          const pf = item.t.substring(0,50).toLowerCase();
          const hasFact = rec.facts.some(function(f){ return String(f.t||'').substring(0,50).toLowerCase() === pf; });
          if(!hasFact){
            rec.facts.push({ t:item.t, ts:now, topic:top0 });
            if(rec.facts.length > 8) rec.facts.splice(0, rec.facts.length - 8);
            ech = true;
          }
          for(let j=0;j<entities.length;j++){
            if(entities[j] === en) continue;
            const hasN = rec.neighbors.some(function(n){ return n.e === entities[j]; });
            if(!hasN){
              rec.neighbors.push({ e:entities[j], ts:now, topic:top0, evidence:text.substring(0,120) });
              ech = true;
            }
            if(rec.neighbors.length > 6) rec.neighbors.splice(0, rec.neighbors.length - 6);
          }
        }
        if(ech) await kvPut('memory_entities', ents);
      }catch(e){}
      // 3) Link antar entitas (jaringan fakta)
      try{
        const links = await memoryLinksGet();
        const top0 = topics[0] || 'umum';
        let lch = false;
        for(let i=0;i<entities.length;i++){
          for(let j=0;j<entities.length;j++){
            if(entities[i] === entities[j]) continue;
            const a = entities[i], b = entities[j];
            let ex = null;
            for(let l=0;l<links.length;l++){ const L=links[l]; if((L.a===a&&L.b===b)||(L.a===b&&L.b===a)){ ex=L; break; } }
            if(ex){ ex.evidence = text.substring(0,120); ex.ts = now; ex.topic = top0; ex.str = Math.min(1,(ex.str!=null?ex.str:0.5)+0.08); }
            else { links.push({ a:a, b:b, rel:'disebut bersama', evidence:text.substring(0,120), ts:now, topic:top0, str:0.5 }); }
            lch = true;
          }
        }
        if(links.length > 80) links.splice(0, links.length - 80);
        if(lch) await kvPut('memory_links', links);
      }catch(e){}
    }
  }catch(e){}
}

// Ringkas topik yang sudah punya >=4 item (batched, hemat kuota)
async function refreshTopicSummaries(idx, budget){
  let done = 0;
  const limit = budget || 2;
  for(let i=0;i<idx.length && done<limit;i++){
    const entry = idx[i] || {};
    const items = entry.items || [];
    if(items.length < 4 || !items[items.length-1]) continue;
    if(entry.summaryTs && (items[items.length-1].ts||0) <= entry.summaryTs) continue;
    let sum = '';
    try{
      const sample = items.slice(-4).map(function(x){ return String(x.t||''); }).join(' | ');
      const ai = await smartAIReply([{role:'user', content:'Ringkas jadi 1-2 kalimat bahasa Indonesia santai, inti catatan topik "' + String(entry.topic||'') + '" ini. Jangan tambah info baru:\n\n' + sample.substring(0,700)}], 200);
      if(ai && ai.trim().length > 12) sum = ai.trim().substring(0,320);
    }catch(e){}
    if(!sum){
      const bits = items.slice(-3).map(function(x){ return String(x.t||'').substring(0,80); });
      sum = bits.join(' | ');
    }
    entry.summary = sum;
    entry.summaryTs = Date.now();
    done++;
  }
  // Agregasi mood per topik (untuk penandaan emosi ala amygdala)
  for(let i=0;i<idx.length;i++){
    const counts = {};
    const items = idx[i].items || [];
    for(let j=0;j<items.length;j++){
      const m = items[j].mood || 'umum';
      counts[m] = (counts[m]||0) + 1;
    }
    idx[i].moods = counts;
  }
  return done;
}

// ==== MEKANISME OTAK: kekuatan sinaps, pelupaan, konsolidasi ====
const DECAY_DAILY = 0.88;
const FORGET_STR = 0.12;
const FORGET_DAYS = 45;

function effectiveStrength(it, now){
  if(!it) return 0;
  if(it.pinned) return 1;
  const days = Math.max(0, (now - (it.ts||now)) / 86400000);
  let s = (it.str != null ? it.str : (0.5 + (it.imp||4)*0.05));
  for(let i=0;i<Math.floor(days);i++) s *= DECAY_DAILY;
  return Math.max(0, Math.min(1, s));
}

function memScore(it){
  const now = Date.now();
  const s = effectiveStrength(it, now);
  const imp = (it.imp != null ? it.imp : 4) / 10;
  const days = Math.max(0, (now - (it.ts||now)) / 86400000);
  const rec = days < 1 ? 0.25 : days < 7 ? 0.15 : days < 30 ? 0.05 : 0;
  return s + imp + rec;
}

// Pelupaan terencana: yang lemah + lama + gak penting dirapikan (kecuali di-pin)
async function decayMemory(){
  const now = Date.now();
  let changed = false;
  try{
    const idx = await memoryIndexGet();
    for(let e=0;e<idx.length;e++){
      const entry = idx[e] || {};
      const items = entry.items || [];
      for(let i=items.length-1;i>=0;i--){
        const it = items[i] || {};
        if(it.pinned) continue;
        it.str = effectiveStrength(it, now);
        const days = (now - (it.ts||now)) / 86400000;
        if(it.str < FORGET_STR && days > FORGET_DAYS && (it.imp||4) < 7) items.splice(i,1);
      }
      if(items.length){
        let sumS = 0;
        for(let i=0;i<items.length;i++) sumS += (items[i].str != null ? items[i].str : 0.6);
        entry.str = sumS / items.length;
      }
    }
    for(let i=idx.length-1;i>=0;i--){
      if(!(idx[i].items||[]).length) idx.splice(i,1);
    }
    await kvPut('memory_index', idx);
    changed = true;
  }catch(e){}
  try{
    const links = await memoryLinksGet();
    const before = links.length;
    for(let i=links.length-1;i>=0;i--){
      const L = links[i] || {};
      const days = (now - (L.ts||now)) / 86400000;
      if(days > FORGET_DAYS && !L.pinned) links.splice(i,1);
    }
    if(links.length !== before) await kvPut('memory_links', links);
  }catch(e){}
  // Loose ends >45 hari & belum kelar -> diarsipkan (done) biar gak muncul terus
  try{
    const ends = await kvGet('loose_ends') || [];
    let arch = 0;
    const cutoff = now - 45*24*3600*1000;
    for(let i=0;i<ends.length;i++){ if(!ends[i].done && ends[i].ts < cutoff){ ends[i].done = true; arch++; } }
    if(arch > 0) await kvPut('loose_ends', ends);
  }catch(e){}
  return changed;
}


// --- OTAK: konsolidasi memori mirip (jalankan saat sleep) ---
async function consolidateSimilarMemories(){
  let merged = 0;
  try{
    const idx = await memoryIndexGet();
    let ch = false;
    for(let e=0;e<idx.length;e++){
      const entry = idx[e] || {};
      const items = entry.items || [];
      for(let i=items.length-1;i>=0;i--){
        const A = items[i] || {};
        if(A.pinned) continue;
        for(let j=i-1;j>=0;j--){
          const B = items[j] || {};
          if(B.pinned) continue;
          const sim = memSimilarity(A.t, B.t);
          if(sim < 0.55) continue;
          // Gabung: ambil teks terpanjang, strength ditambah, imp max, ts terbaru
          const keep = (String(B.t||'').length >= String(A.t||'').length) ? B : A;
          const drop = (keep === B) ? A : B;
          keep.str = Math.min(1, (keep.str != null ? keep.str : 0.6) + Math.min(0.2, (drop.str != null ? drop.str : 0.6) * 0.15));
          keep.imp = Math.max(keep.imp||4, drop.imp||4);
          keep.ts = Math.max(keep.ts||0, drop.ts||0);
          keep.conf = (keep.conf === 'yakin' || drop.conf === 'yakin') ? 'yakin' : 'ragu';
          items.splice(items.indexOf(drop), 1);
          merged++;
          ch = true;
        }
      }
      if(entry.maxItems && entry.items.length > entry.maxItems) entry.items.splice(0, entry.items.length - entry.maxItems);
    }
    if(ch) await kvPut('memory_index', idx);
  }catch(e){}
  return merged;
}


// --- OTAK: pembersih skill kosong (nama tanpa implementasi) ---
const EMPTY_SKILL_NAMES = ["CHAIN-OF-THOUGHT","MEMORY-COMPRESSION","EMOTIONAL-TRAJECTORY","CONTEXTUAL-NETWORK","SMART-PROACTIVE","SESSION-INTELLIGENCE","ADVANCED-CODE","MULTI-PERSONA","REAL-TIME-AWARENESS","INTELLIGENCE-GROWTH","RISK-ASSESSMENT","CONSEQUENCE-PREDICTION","BEHAVIOR-CALIBRATION","RECOVERY-PROTOCOL","PWA-OFFLINE-MODE","SEARCH-RESULT-SYNTHESIS","SOURCE-VERIFICATION","KNOWLEDGE-GAP-DETECTION","EMOTIONAL-VOICE-SYNTHESIS","VOICE-PERSONALITY-MAPPING","SMART-GOAL-SUGGESTIONS","HABIT-TRACKING","WORKFLOW-AUTOMATION","SMART-NOTIFICATION","ANALYTICS-EXPORT","AUTO-DOCUMENTATION","DATA-SYNC","FINANCIAL-TRACKING","FINANCIAL-BUDDY","PERFORMANCE-METRICS","NEGOTIATION-SKILLS","PUBLIC-SPEAKING","CONFLICT-RESOLUTION","PERSUASION-TECHNIQUE","MULTI-LANGUAGE-CHAT","SOCIAL-DYNAMICS","CONVERSATION-ANALYSIS","CONVERSATION-INTELLIGENCE","EMOTIONAL-TRAJECTORY","EMOTIONAL-REGULATION","PROACTIVE-THINKING","PROACTIVE-COMMUNICATION","SELF-EVOLUTION","SELF-IDENTITY-DIARY","ACHIEVEMENT-SYSTEM","INTELLIGENCE-GROWTH-TRACKER","SMART-CONTEXT-CACHE","COLOR-THEORY","TYPOGRAPHY","DELEGATION"];
async function cleanupEmptySkills(){
  try{
    const sk = await kvGet('implemented_skills') || [];
    const before = sk.length;
    const cleaned = sk.filter(function(s){
      const name = (typeof s === 'string') ? s : (s.name || '');
      return EMPTY_SKILL_NAMES.indexOf(name) === -1;
    });
    if(cleaned.length === before) return 0;
    await kvPut('implemented_skills', cleaned);
    return before - cleaned.length;
  }catch(e){ return 0; }
}


