// INNER-VOICE WEEKLY: deeper reflection (run weekly)
async function generateWeeklyReflection(){
  try{
    const trend = await kvGet('mood_trend') || {history:[], daily:{}};
    const weekAgo = Date.now() - 7*24*3600*1000;
    const weekEntries = trend.history.filter(function(h){ return h.ts > weekAgo; });
    if(weekEntries.length < 5) return false;
    const moodCounts = {};
    weekEntries.forEach(function(h){moodCounts[h.mood]=(moodCounts[h.mood]||0)+1;});
    const dominant = Object.entries(moodCounts).sort(function(a,b){return b[1]-a[1];})[0];
    const moodLabel = {senang:'happy',serius:'serius',motivasi:'penuh semangat',fokus:'fokus',rileks:'santai',kaget:'kaget',khawatir:'khawatir',idle:'idle'};
    const label = moodLabel[dominant[0]] || dominant[0];
    let text = '';
    try{
      const ai = await smartAIReply([{role:'user', content:'Kamu Adaptia. Minggu ini mood lu dominan "' + label + '" (' + dominant[1] + ' kali dari ' + weekEntries.length + ' interaksi). Tulis refleksi mingguan 1-2 kalimat, bahasa gaul. Format: "minggu ini gw dominan ngerasa X... Y". Jangan pakai emoji.'}], 200);
      if(ai && ai.trim().length > 15) text = ai.trim().substring(0, 250);
    }catch(e){}
    if(!text) text = 'Minggu ini gw dominan ngerasa ' + label + ' (' + dominant[1] + ' kali). Cukup stabil sih.';
    const pers = await getPersona();
    if(!pers.innerVoice) pers.innerVoice = [];
    pers.innerVoice.push({ ts: Date.now(), text: text, layer: 'weekly', mood: dominant[0] });
    if(pers.innerVoice.length > 40) pers.innerVoice.splice(0, pers.innerVoice.length - 40);
    await kvPut('persona', pers);
    return true;
  }catch(e){ return false; }
}

