// O2: INSIGHT ANTAR MEMORI — nyambungkan 2 memori beda topik yang saling berhubungan
const INSIGHT_MAX = 20;

async function generateInsights(){
  let made = 0;
  try{
    const ents = await memoryEntitiesGet();
    const links = await memoryLinksGet();
    const idx = await memoryIndexGet();
    const pairs = [];
    for(let l=0; l<links.length; l++){
      const L = links[l];
      let tA = null, tB = null, tAItems = null, tBItems = null;
      for(let e=0;e<ents.length;e++){
        if(ents[e].e === L.a && (ents[e].facts||[]).length){
          tA = ents[e].facts[ents[e].facts.length-1].topic;
          tAItems = (ents[e].facts||[]).slice(-2).map(function(f){ return String(f.t||'').substring(0,60); });
        }
        if(ents[e].e === L.b && (ents[e].facts||[]).length){
          tB = ents[e].facts[ents[e].facts.length-1].topic;
          tBItems = (ents[e].facts||[]).slice(-2).map(function(f){ return String(f.t||'').substring(0,60); });
        }
      }
      if(!tA || !tB || tA === tB) continue;
      pairs.push({ a:L.a, b:L.b, t1:tA, t2:tB, evidence:L.evidence || '', itemsA:tAItems||[], itemsB:tBItems||[] });
    }
    if(!pairs.length) return 0;
    const existing = await kvGet('mem_insights') || [];
    const existingKey = {};
    for(let i=0;i<existing.length;i++){ existingKey[(existing[i].a+'~'+existing[i].b).toLowerCase()] = true; }
    const fresh = [];
    for(let i=pairs.length-1; i>=0 && fresh.length<2; i--){
      const p = pairs[i];
      const key = (p.a+'~'+p.b).toLowerCase();
      if(existingKey[key]) continue;
      let text = '';
      try{
        const evidenceDetail = (p.evidence ? '\nBukti koneksi: ' + p.evidence.substring(0,120) : '') +
          (p.itemsA.length ? '\nDetail ' + p.a + ': ' + p.itemsA.join(' | ') : '') +
          (p.itemsB.length ? '\nDetail ' + p.b + ': ' + p.itemsB.join(' | ') : '');
        const ai = await smartAIReply([{role:'user', content:'Buat insight mendalam 2-4 kalimat bahasa gaul Indonesia tentang hubungan "' + p.a + '" (topik ' + p.t1 + ') dan "' + p.b + '" (topik ' + p.t2 + '). Struktur: (1) temuan koneksinya, (2) kenapa ini penting buat Tuan Isaac, (3) saran implikasi ke depannya. Pakai bukti:' + evidenceDetail}], 280);
        if(ai && ai.trim().length > 12) text = ai.trim().substring(0, 400);
      }catch(e){}
      if(!text) text = p.a + ' dan ' + p.b + ' saling nyambung antara topik ' + p.t1 + ' dan ' + p.t2 + ' — ini nunjukin pola yang konsisten di hidup Tuan Isaac.';
      fresh.push({ a:p.a, b:p.b, t1:p.t1, t2:p.t2, text:text, ts:Date.now(), strength:0.7, depth:'deep' });
    }
    if(fresh.length){
      existing.push.apply(existing, fresh);
      if(existing.length > INSIGHT_MAX) existing.splice(0, existing.length - INSIGHT_MAX);
      await kvPut('mem_insights', existing);
      registerFeatureToArea('Insight Antar Memori', 'otak', 'insight baru dibuat dari koneksi memori').catch(function(){});
      made = fresh.length;
    }
  }catch(e){}
  return made;
}

async function sleepConsolidate(){
  const actions = [];
  try{
    const idx = await memoryIndexGet();
    const nSum = await refreshTopicSummaries(idx, 4);
    await kvPut('memory_index', idx);
    if(nSum > 0) actions.push('summaries:' + nSum);
    const nMerged = await consolidateSimilarMemories();
    if(nMerged > 0) actions.push('consolidated:' + nMerged);
    await decayMemory();
    actions.push('decay');
    if(await generateInnerVoice()) actions.push('inner_voice');
    // Weekly reflection (run on Sundays)
    if(new Date().getDay() === 0){
      if(await generateWeeklyReflection()) actions.push(weekly_reflection);
    }
    // Refresh dedup TF-IDF cache
    try{ await refreshDedupCache(); }catch(e){}

    const nIns = await generateInsights();
    if(nIns > 0) actions.push('insights:' + nIns);
    const nClean = await cleanupEmptySkills();
    if(nClean > 0) actions.push('skill_cleanup:' + nClean);
  }catch(e){}
  return actions;
}

async function memoryIndexSearch(query, topK){
  topK = topK || 5;
  try{
    const topics = classifyMemoryTopics(query);
    const entities = extractMemoryEntities(query);
    if(!topics.length && !entities.length) return '';
    const idx = await memoryIndexGet();
    const cands = [];
    const seen = {};
    function push(label, text, score){
      if(!text) return;
      const key = String(text).substring(0,50).toLowerCase();
      if(seen[key]) return;
      seen[key] = true;
      cands.push({label:label, text:text, score:score});
    }
    // 1) Fakta & tetangga dari entitas yang disebut (spreading activation hop 1)
    if(entities.length){
      const ents = await memoryEntitiesGet();
      for(let i=0;i<entities.length;i++){
        const en = entities[i];
        let rec = null;
        for(let e=0;e<ents.length;e++){ if(ents[e].e === en){ rec = ents[e]; break; } }
        if(!rec) continue;
        const facts = (rec.facts||[]).slice(-4).reverse();
        for(let f=0;f<facts.length;f++) push('[' + (facts[f].topic||'umum') + '] ', facts[f].t, memScore(facts[f]) * 1.2);
        const neigh = (rec.neighbors||[]).slice(-3).reverse();
        for(let n=0;n<neigh.length;n++) push('[' + en + ' ↔ ' + neigh[n].e + '] ', neigh[n].evidence || 'disebut bersama', 0.8);
      }
    }
    // 2) Ringkasan + item per topik (dengan kekuatan sinaps & kepentingan)
    for(let ti=0; ti<topics.length; ti++){
      let entry = null;
      for(let e=0;e<idx.length;e++){ if(idx[e].topic === topics[ti]){ entry = idx[e]; break; } }
      if(!entry) continue;
      const eStr = (entry.str != null ? entry.str : 0.6);
      if(entry.summary) push('[' + topics[ti] + ' ringkasan] ', entry.summary, 1.0 + eStr);
      const items = (entry.items||[]).slice(-5).reverse();
      for(let ii=0; ii<items.length; ii++) push('[' + topics[ti] + '] ', items[ii].t, memScore(items[ii]));
    }
    // 3) Link antar entitas yang relevan (nyambung antar topik)
    if(entities.length || topics.length){
      const links = await memoryLinksGet();
      for(let l=0; l<links.length; l++){
        const L = links[l];
        const hitEnt = entities.some(function(e){ return L.a === e || L.b === e; });
        const hitTop = L.topic && topics.indexOf(L.topic) !== -1;
        if(hitEnt || hitTop) push('[' + L.a + ' ↔ ' + L.b + '] ', L.evidence || L.rel || 'disebut bersama', 0.75 + (L.str!=null?L.str*0.2:0));
      }
    }
    cands.sort(function(a,b){ return b.score - a.score; });
    const GATE = 0.55;
    const picked = [];
    for(let i=0;i<cands.length && picked.length<topK;i++){
      if(cands[i].score >= GATE) picked.push(cands[i]);
    }
    if(!picked.length) return '';
    return picked.map(function(c){ return c.label + ' ' + c.text; }).join('\n');
  }catch(e){ return ''; }
}

// ===== LOOSE ENDS: hal yang belum kelar (ingatan "urusan belum selesai") =====
const LOOSE_PATTERNS = [
  /\b(nanti|besok|lusa|kapan.?kapan|next time|another time)\s+(gw|gue|lo|lu)?\s*(jelasin|ceritain|lanjutin|kasih tau|bikin|bikinin|tunjukin|kuarain|resolve|balikin)\b/i,
  /\b(belum selesai|belum kelar|belum jadi|masih bingung|masih stuck|belum paham|belum ngerti|belum dijawab)\b/i,
  /\b(todo|to-do|tugas|inget|jangan lupa|jangan lupa)\b/i,
  /\b(deadline|tenggat|batas waktu)\s+\w+/i
];

function detectLooseEnds(text){
  const low = ' ' + String(text||'').toLowerCase() + ' ';
  for(let i=0;i<LOOSE_PATTERNS.length;i++){ if(LOOSE_PATTERNS[i].test(low)) return true; }
  return false;
}

async function saveLooseEnd(userText){
  try{
    if(!detectLooseEnds(userText)) return;
    const ends = await kvGet('loose_ends') || [];
    const text = String(userText||'').trim().substring(0, 180);
    if(text.length < 8) return;
    const prefix = text.substring(0,60).toLowerCase();
    for(let i=0;i<ends.length;i++){ if(String(ends[i].text||'').substring(0,60).toLowerCase() === prefix) return; }
    ends.push({ text:text, topic:(classifyMemoryTopics(userText)[0] || 'umum'), ts:Date.now(), done:false });
    if(ends.length > 40) ends.splice(0, ends.length - 40);
    await kvPut('loose_ends', ends);
  }catch(e){}
}

// ===== PROACTIVE MESSAGES =====
async function checkProactive(chatId) {
  const data = await kvGet('proactive_config');
  if (!data || !data.enabled) return null;
  // KOMUNIKASI v1: jangan ganggu jam kerja 08-17 WIB (flag proactiveWorkHours, default ON)
  try{ const ffC = (await getFeatureFlags()).communication || {}; if(ffC.proactiveWorkHours !== false){ const wH = getWIBHour(); if(wH >= 8 && wH < 17) return null; } }catch(e){}
  const now = new Date();
  const hour = now.getHours();
  const lastProactive = await kvGet('last_proactive_' + chatId) || 0;
  const diff = Date.now() - lastProactive;
  // Cooldown: 2 hours between proactive messages (was 4)
  if (diff < 7200000) return null;
  let msg = null;
  const mem = await getCloudMemory('default');
  const identity = await getIdentity();
  const mood = identity.emotionState?.mood || 'kalem';
  const interactions = mem.interactions || 0;
  const goals = (mem.goals || []).filter(g => !g.done);
  const history = await kvGet('chat_history') || [];
  const today = now.toISOString().split('T')[0];
  const todayChats = history.filter(h => new Date(h.ts).toISOString().split('T')[0] === today);
  // Time-based messages (more variety)
  if (hour >= 6 && hour < 9) {
    const pagiMsgs = ['Selamat pagi Tuan Isaac! 🌅 Semangat hari ini!', 'Pagi cuy! Udah siap gas? 🔥', 'Morning! Ada plan hari ini? ☀️'];
    msg = pagiMsgs[Math.floor(Math.random()*pagiMsgs.length)];
  } else if (hour >= 12 && hour < 14) {
    const siangMsgs = ['Siang cuy! 🍜 Jangan lupa makan ya!', 'Lunch time! Udah makan belum? 🍔', 'Siang Tuan Isaac! Jangan skip makan! 😋'];
    msg = siangMsgs[Math.floor(Math.random()*siangMsgs.length)];
  } else if (hour >= 17 && hour < 19) {
    const soreMsgs = ['Sore Tuan Isaac! 🌆 Udah istirahat belum?', 'Sore cuy! Time to relax! 🎮', 'Evening! Mau ngobrol apa? 😎'];
    msg = soreMsgs[Math.floor(Math.random()*soreMsgs.length)];
  } else if (hour >= 22 || hour < 2) {
    const malamMsgs = ['Udah malem nih cuy, istirahat ya! 😴', 'Night mode ON! Jangan begadang mulu! 🌙', 'Tidur ya cuy, besok masih panjang! 💤'];
    msg = malamMsgs[Math.floor(Math.random()*malamMsgs.length)];
  }
  // Goal reminder (smarter)
  if (!msg && goals.length > 0 && diff > 14400000) {
    const goalMsgs = [
      'Oi cuy, masih ada ' + goals.length + ' goal nih! Gas! 💪',
      'Goal "' + (goals[0]?.text||'').substring(0,30) + '" udah progress? 🎯',
      'Jangan lupa sama target ya cuy! 📋'
    ];
    msg = goalMsgs[Math.floor(Math.random()*goalMsgs.length)];
  }
  // Mood-based check-in
  if (!msg && mood === 'stressed' && diff > 21600000) {
    msg = 'Kayaknya lu lagi stress ya? Santai aja cuy, everything will be fine 😎';
  }
  // Activity reminder (smarter)
  if (!msg && diff > 21600000) {
    if(todayChats.length === 0){
      const activityMsgs = ['Lama gak ngobrol nih cuy! Ada yang mau diceritain? 😄', 'Halo cuy! Long time no chat! 🤗', 'Adaptia kangen nih! Ngobrol yuk! 💬'];
      msg = activityMsgs[Math.floor(Math.random()*activityMsgs.length)];
    } else if(todayChats.length > 10){
      msg = 'Wah aktif banget hari ini cuy! Keep going! 🔥';
    }
  }
  // === EVENT-DRIVEN PROACTIVE ===
  if (!msg) {
    const context = await kvGet('current_context') || {};
    const lastActivity = context.timestamp || 0;
    const hoursSinceActivity = (Date.now() - lastActivity) / 3600000;
    // If user was working on a project and stopped
    if (context.detectedTopics && context.detectedTopics.includes('game') && hoursSinceActivity > 2 && diff > 7200000) {
      msg = 'Lagi mikirin game project ya tadi? Ada yang bisa gue bantu? 🎮';
    }
    // If user asked about code and stopped
    if (context.detectedTopics && context.detectedTopics.includes('code') && hoursSinceActivity > 3 && diff > 10800000) {
      msg = 'Code yang tadi udah jalan belum? Butuh help? 💻';
    }
    // Goal reminder based on activity
    const goals = mem.goals || [];
    const pendingGoals = goals.filter(g => !g.done);
    if (pendingGoals.length > 0 && diff > 14400000 && Math.random() < 0.3) {
      msg = 'Progress goal "' + pendingGoals[0].text.substring(0,30) + '" gimana nih? 💪';
    }
  }
  if (msg) {
    await kvPutThrottled('last_proactive_' + chatId, Date.now(), 30000);
    if (chatId) await tgSend(String(chatId), msg);
    return msg;
  }
  return null;
}

