async function checkReminders() {
  const key = 'reminders_default';
  const reminders = (await kvGet(key)) || [];
  const now = Date.now();
  const chatId = await kvGet('tg_chat_id');
  let changed = false;
  for (const r of reminders) {
    if (!r || !r.time || !r.text || isNaN(new Date(r.time).getTime())) {
      // entri rusak: tandai sent biar dibersihkan dari daftar pending
      if (r && !r.sent) { r.sent = true; changed = true; }
      continue;
    }
    if (!r.sent && new Date(r.time).getTime() <= now) {
      r.sent = true;
      changed = true;
      if (chatId) await tgSend(chatId, '⏰ Reminder dari Adaptia: ' + r.text);
      try{ await pushAll('⏰ Reminder dari Adaptia', String(r.text||'').slice(0,240), '/'); }catch(e){}
    }
  }
  if (changed) await kvPut(key, reminders);
  return reminders.filter(r => !r.sent);
}

// ===== WEB SEARCH (Bing HTML scraping primary + DuckDuckGo lite fallback) =====
async function bingSearch(query) {
  const r = await fetch('https://www.bing.com/search?q=' + encodeURIComponent(query) + '&setlang=id&cc=ID', {
    headers: {'User-Agent': 'Mozilla/5.0 (iPhone; CPU iPhone OS 16_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/16.0 Mobile/15E148 Safari/604.1', 'Accept-Language': 'id-ID,id;q=0.9,en;q=0.8'}
  });
  const html = await r.text();
  const blocks = html.match(/<li class="b_algo".*?<\/li>/gs) || [];
  const results = [];
  for (const b of blocks.slice(0, 5)) {
    const titleM = b.match(/<h2[^>]*>\s*<a[^>]*>(.*?)<\/a>/s);
    const citeM = b.match(/<cite[^>]*>(.*?)<\/cite>/s);
    const snipM = b.match(/<p[^>]*>(.*?)<\/p>/s);
    if (titleM) {
      const title = titleM[1].replace(/<[^>]+>/g, '').trim();
      const url = citeM ? citeM[1].replace(/<[^>]+>/g, '').trim() : '';
      const snip = snipM ? snipM[1].replace(/<[^>]+>/g, '').trim() : '';
      if (title && url) results.push({ title: title.substring(0, 120), url: url.substring(0, 120), snippet: snip.substring(0, 200) });
    }
  }
  return results;
}

async function ddgSearch(query) {
  const r = await fetch('https://html.duckduckgo.com/html/?q=' + encodeURIComponent(query), {
    headers: {'User-Agent': 'Mozilla/5.0 (iPhone; CPU iPhone OS 16_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/16.0 Mobile/15E148 Safari/604.1', 'Accept-Language': 'id-ID,id;q=0.9,en;q=0.8'}
  });
  const html = await r.text();
  const blocks = html.match(/<div class="result results_links.*?<\/div>\s*<\/div>/gs) || [];
  const results = [];
  for (const b of blocks.slice(0, 5)) {
    const titleM = b.match(/<a[^>]*class="result__a"[^>]*>(.*?)<\/a>/s);
    const snipM = b.match(/<a[^>]*class="result__snippet"[^>]*>(.*?)<\/a>/s);
    const urlM = b.match(/class="result__url"[^>]*>(.*?)<\//s);
    if (titleM) {
      const title = titleM[1].replace(/<[^>]+>/g, '').trim();
      let rawUrl = '';
      const hrefM = titleM[0].match(/href="([^"]+)"/);
      if (hrefM) {
        rawUrl = hrefM[1].replace(/&amp;/g, '&');
        const uddg = rawUrl.match(/uddg=([^&]+)/);
        if (uddg) rawUrl = decodeURIComponent(uddg[1]);
        else if (rawUrl.indexOf('//') === 0) rawUrl = 'https:' + rawUrl;
      }
      if (!rawUrl && urlM) rawUrl = urlM[1].replace(/<[^>]+>/g, '').trim();
      if (!/^https?:\/\//i.test(rawUrl) && rawUrl.indexOf('www.') === 0) rawUrl = 'https://' + rawUrl;
      const snip = snipM ? snipM[1].replace(/<[^>]+>/g, '').trim() : '';
      if (title && rawUrl) results.push({ title: title.substring(0, 120), url: rawUrl.substring(0, 150), snippet: snip.substring(0, 200) });
    }
  }
  return results;
}

// Wikipedia search — fallback faktual & sangat reliable dari CF Workers
async function wikiSearch(query) {
  const r = await fetch('https://id.wikipedia.org/w/api.php?action=query&list=search&srsearch=' + encodeURIComponent(query) + '&format=json&srlimit=5&utf8=1', {
    headers: {'User-Agent': 'AdaptiaBot/1.0 (PWA assistant; contact: none)'}
  });
  const data = await r.json();
  const hits = (data.query && data.query.search) || [];
  const results = [];
  for (const h of hits.slice(0, 5)) {
    const title = (h.title || '').trim();
    const snip = (h.snippet || '').replace(/<[^>]+>/g, '').trim();
    if (title) results.push({ title: title.substring(0, 120), url: 'https://id.wikipedia.org/wiki/' + encodeURIComponent(title.replace(/ /g, '_')), snippet: snip.substring(0, 200) });
  }
  return results;
}

// Return array of {title,url,snippet} — buat /api/search (frontend)
async function webSearchResults(query) {
  try {
    const bing = await bingSearch(query);
    if (bing.length) return bing;
  } catch(e) {}
  try {
    const ddg = await ddgSearch(query);
    if (ddg.length) return ddg;
  } catch(e) {}
  try {
    const wiki = await wikiSearch(query);
    if (wiki.length) return wiki;
  } catch(e) {}
  return [];
}

