// === TIME-AWARE UPGRADE: Activity Patterns + Scheduled Awareness ===
function getTimeInfo() {
  const now = new Date();
  const hours = now.getHours();
  const mins = now.getMinutes();
  let period = '';
  if (hours >= 5 && hours < 11) period = 'Pagi';
  else if (hours >= 11 && hours < 15) period = 'Siang';
  else if (hours >= 15 && hours < 18) period = 'Sore';
  else period = 'Malam';
  const date = now.toLocaleDateString('id-ID', {timeZone:'Asia/Jakarta', weekday:'long', day:'numeric', month:'long', year:'numeric'});
  const time = now.toLocaleTimeString('id-ID', {timeZone:'Asia/Jakarta', hour:'2-digit', minute:'2-digit'});
  return { text: time + ' WIB (' + period + ')', period, date, time };
}

// Track activity time windows (kapan Tuan biasanya ngobrol)
async function recordActivityTime(){
  try{
    const h = getWIBHour();
    const day = new Date().getDay();
    const act = await kvGet('activity_pattern') || {windows:{}, total:0};
    const wKey = h;
    if(!act.windows[wKey]) act.windows[wKey] = {count:0, days:{}};
    act.windows[wKey].count++;
    act.windows[wKey].days[day] = (act.windows[wKey].days[day]||0) + 1;
    act.total++;
    await kvPut('activity_pattern', act);
  }catch(e){}
}

// Get Tuan's most active time windows
async function getActivityContext(){
  try{
    const act = await kvGet('activity_pattern') || {windows:{}, total:0};
    if(act.total < 10) return '';
    const windows = Object.entries(act.windows).sort(function(a,b){ return b[1].count - a[1].count; }).slice(0,3);
    if(!windows.length) return '';
    const parts = windows.map(function(w){
      const h = parseInt(w[0]);
      let label = h + ':00';
      if(h >= 0 && h < 6) label = 'dini hari';
      else if(h >= 6 && h < 12) label = 'pagi';
      else if(h >= 12 && h < 15) label = 'siang';
      else if(h >= 15 && h < 18) label = 'sore';
      else label = 'malam';
      return label + ' (' + w[1].count + 'x)';
    });
    return '\nJAM AKTIF TUAN: biasanya aktif di ' + parts.join(', ') + '. Sesuaikan energi/sapaan.';
  }catch(e){ return ''; }
}

// Contextual time response based on hour + activity
async function getTimeAwareContext(){
  try{
    const hour = getWIBHour();
    let ctx = '';
    const h = hour;
    if(h >= 0 && h < 5) ctx = 'Tuan masih begadang — jaga bahasa tetap tenang, tawarkan istirahat bila pas.';
    else if(h >= 5 && h < 9) ctx = 'Pagi hari — energi Tuan biasanya tinggi, semangatkan aktivitas.';
    else if(h >= 9 && h < 12) ctx = 'Lagi jam produktif — jawaban to the point, fokus bantu kerjaan.';
    else if(h >= 12 && h < 14) ctx = 'Jam makan siang — tanyakan sudah makan, jangan terlalu formal.';
    else if(h >= 14 && h < 17) ctx = 'Sore hari — work hours, bantu yang praktis.';
    else if(h >= 17 && h < 19) ctx = 'Waktu pulang kerja — santai, tawarkan rehat.';
    else if(h >= 19 && h < 22) ctx = 'Malam — waktu santai, obrolan lebih cair.';
    else ctx = 'Malam larut — Tuan mungkin lelah, jawaban singkat & perhatian.';
    return '\n== TIME AWARENESS ==\n' + ctx;
  }catch(e){ return ''; }
}


