// ===== SELF-REPAIR: deteksi & fix data korup, balikin dari backup kalau ada =====
async function selfRepair() {
  const fixed = [];
  try {
    // 1. Memory core
    const mem = await getCloudMemory('default');
    if (!mem.facts) { mem.facts = []; fixed.push('Memory facts'); }
    if (!mem.goals) { mem.goals = []; fixed.push('Memory goals'); }
    if (!mem.projects) { mem.projects = ['FightingGame Madara','Game MUGEN','Adaptia']; fixed.push('Memory projects'); }
    if (!mem.dailyNotes) { mem.dailyNotes = []; fixed.push('Memory notes'); }
    if (!mem.insights) { mem.insights = []; fixed.push('Memory insights'); }
    await saveCloudMemory('default', mem);
  } catch(e) {}
  try {
    // 2. Identity
    const identity = await getIdentity();
    if (!identity.diary) { identity.diary = []; fixed.push('Identity diary'); }
    if (!identity.emotionState) { identity.emotionState = {mood:'kalem',energy:70,since:new Date().toISOString()}; fixed.push('Identity emotion'); }
    await saveIdentity(identity);
  } catch(e) {}
  try {
    // 3. Chat history harus array (bukan string/null)
    const hist = await kvGet('chat_history');
    if (hist && !Array.isArray(hist)) { await kvPut('chat_history', []); fixed.push('Chat history rusak'); }
  } catch(e) {}
  try {
    // 4. Rolling summaries harus array
    const rs = await kvGet('rolling_summaries');
    if (rs && !Array.isArray(rs)) { await kvPut('rolling_summaries', []); fixed.push('Rolling summaries'); }
  } catch(e) {}
  try {
    // 5. Stories harus array
    const st = await kvGet('stories');
    if (st && !Array.isArray(st)) { await kvPut('stories', []); fixed.push('Stories'); }
  } catch(e) {}
  try {
    // 6. RAG memories harus array
    const rag = await kvGet('rag_memories');
    if (rag && !Array.isArray(rag)) { await kvPut('rag_memories', []); fixed.push('RAG memory'); }
  } catch(e) {}
  try { if (fixed.length) await recordSelfNarrative('Gw ngedeteksi ' + fixed.length + ' hal rusak & berhasil gw beresin sendiri (' + fixed.slice(0,3).join(', ') + ').', 'heal'); } catch(e) {}
  return fixed;
}


