// ===== AUTO-SUMMARY DEEP MEMORY =====
async function autoSummary(chatHistory) {
  try {
    if (!chatHistory || chatHistory.length < 3) return;
    const recent = chatHistory.slice(-6);
    const summary = recent.map(h => (h.text || '').substring(0, 60)).join(' | ');
    const existing = await kvGet('daily_summaries') || [];
    const today = new Date().toISOString().split('T')[0];
    const entry = { date: today, ts: Date.now(), summary: summary };
    // Check if today already has entry
    const todayIdx = existing.findIndex(e => e.date === today);
    if (todayIdx >= 0) {
      existing[todayIdx].summary += ' || ' + summary;
    } else {
      existing.push(entry);
    }
    // Keep last 30 days only
    if (existing.length > 30) existing.splice(0, existing.length - 30);
    await kvPut('daily_summaries', existing);
  } catch(e) {}
}

