// === HABIT TRACKING: Track Tuan's patterns ===

async function trackHabit(text) {
  try {
    const hour = getWIBHour();
    const day = new Date().getDay();
    const topics = classifyMemoryTopics(text);
    const topic = topics[0] || 'umum';
    
    const habits = await kvGet('habits') || { times: {}, topics: {}, patterns: [] };
    
    // Time patterns
    const timeKey = hour;
    if (!habits.times[timeKey]) habits.times[timeKey] = { count: 0, topics: {} };
    habits.times[timeKey].count++;
    habits.times[timeKey].topics[topic] = (habits.times[timeKey].topics[topic] || 0) + 1;
    
    // Topic patterns per day of week
    const dayKey = 'day_' + day;
    if (!habits.topics[dayKey]) habits.topics[dayKey] = {};
    habits.topics[dayKey][topic] = (habits.topics[dayKey][topic] || 0) + 1;
    
    // Length patterns (short vs long messages)
    const msgLen = String(text).length;
    const lenCategory = msgLen < 20 ? 'short' : msgLen < 100 ? 'medium' : 'long';
    if (!habits.messageLength) habits.messageLength = {};
    habits.messageLength[lenCategory] = (habits.messageLength[lenCategory] || 0) + 1;
    
    await kvPut('habits', habits);
  } catch(e) {}
}

async function getHabitInsights() {
  try {
    const habits = await kvGet('habits') || { times: {}, topics: {}, patterns: [] };
    
    // Most active hours
    const topHours = Object.entries(habits.times).sort(function(a, b) { return b[1].count - a[1].count; }).slice(0, 3);
    
    // Day-of-week patterns
    const dayNames = ['Minggu', 'Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu'];
    const dayPatterns = {};
    for (var d = 0; d < 7; d++) {
      const key = 'day_' + d;
      if (habits.topics[key]) {
        const top = Object.entries(habits.topics[key]).sort(function(a, b) { return b[1] - a[1]; })[0];
        dayPatterns[dayNames[d]] = top ? top[0] : null;
      }
    }
    
    // Message length distribution
    const totalMsgs = Object.values(habits.messageLength || {}).reduce(function(a, b) { return a + b; }, 0);
    const lengthDist = {};
    for (var cat in habits.messageLength) {
      lengthDist[cat] = totalMsgs > 0 ? Math.round((habits.messageLength[cat] / totalMsgs) * 100) : 0;
    }
    
    // Predictions
    const currentHour = getWIBHour();
    const currentDay = dayNames[new Date().getDay()];
    const prediction = {
      hourActivity: habits.times[currentHour] ? habits.times[currentHour].count : 0,
      dayTopic: dayPatterns[currentDay] || null,
      isHighActivityHour: habits.times[currentHour] && habits.times[currentHour].count > 3
    };
    
    return {
      topActiveHours: topHours.map(function(h) { return { hour: h[0] + ':00', count: h[1].count }; }),
      dayPatterns: dayPatterns,
      messageLength: lengthDist,
      prediction: prediction,
      totalTracked: totalMsgs
    };
  } catch(e) { return { topActiveHours: [], dayPatterns: {}, messageLength: {}, prediction: {}, totalTracked: 0 }; }
}

// Habit context for chat injection
async function getHabitContext() {
  try {
    const habits = await kvGet('habits') || { times: {}, topics: {} };
    const currentHour = getWIBHour();
    const w = habits.times[currentHour];
    if (!w || w.count < 2) return '';
    const topTopic = Object.entries(w.topics || {}).sort(function(a, b) { return b[1] - a[1]; })[0];
    let ctx = '\n== HABIT: jam ini Tuan biasanya aktif (' + w.count + 'x)';
    if (topTopic) ctx += ', topik: ' + topTopic[0];
    return ctx + ' ==';
  } catch(e) { return ''; }
}


async function smartCompress(oldMsgs) {
  try {
    if (!oldMsgs || oldMsgs.length < 3) return null;
    
    // 1) Extract key facts
    const userMsgs = oldMsgs.filter(function(h) { return h.role === 'user'; });
    const keyFacts = [];
    const factPatterns = [
      /gw\s+(?:baru|lagi|mau|akan|udah|harus)\s+(.+)/i,
      /project\s+(?:gw|gue|ini|itu)\s+(.+)/i,
      /(?:error|bug|masalah)\s+(.+)/i,
      /(?:nama|umur|alamat|kerja|kuliah)\s+(.+)/i,
      /(?:suka|favorit|hobi)\s+(.+)/i,
      /(?:目标|target|mimpi|impian)\s+(.+)/i
    ];
    userMsgs.forEach(function(h) {
      const t = String(h.text || '');
      factPatterns.forEach(function(p) {
        const m = t.match(p);
        if (m && m[1] && m[1].length > 3) keyFacts.push(m[1].substring(0, 100));
      });
    });
    
    // 2) Detect topic shifts
    const topics = [];
    oldMsgs.forEach(function(h) {
      const t = classifyMemoryTopics(h.text || '')[0];
      if (t && (!topics.length || topics[topics.length - 1] !== t)) topics.push(t);
    });
    
    // 3) Detect decisions made
    const decisions = [];
    oldMsgs.forEach(function(h) {
      const t = String(h.text || '').toLowerCase();
      if (/(oke|baik|setuju|deal|gas|mantap|done|selesai|pilih)/i.test(t) && h.role === 'user') {
        decisions.push(String(h.text || '').substring(0, 80));
      }
    });
    
    // 4) Build compressed summary
    let summary = '';
    try {
      const sample = oldMsgs.slice(-10).map(function(h) {
        return (h.role === 'user' ? 'Tuan' : 'Adaptia') + ': ' + String(h.text || '').substring(0, 80);
      }).join('\n');
      const prompt = 'Ringkas obrolan ini dalam 2-3 kalimat padat. Fokus: topik utama, keputusan, hal penting. Bahasa gaul Indonesia.\n\n' + sample;
      const ai = await smartAIReply([{ role: 'user', content: prompt }], 250);
      if (ai && ai.trim().length > 15) summary = ai.trim().substring(0, 400);
    } catch(e) {}
    
    if (!summary) {
      summary = 'Obrolan tentang ' + (topics.join(', ') || 'hal umum') + '. ' +
        (decisions.length ? 'Keputusan: ' + decisions[decisions.length - 1].substring(0, 60) + '.' : '');
    }
    
    return {
      summary: summary,
      keyFacts: keyFacts.slice(0, 5),
      topics: topics.slice(0, 5),
      decisions: decisions.slice(0, 3),
      msgCount: oldMsgs.length,
      ts: Date.now()
    };
  } catch(e) { return null; }
}

async function enhancedRollMemory(force) {
  try {
    const history = await kvGet('chat_history') || [];
    if (!history || history.length < 4) return null;
    const MAX_KEEP = 30;
    if (history.length <= (force ? 45 : 60)) return null;
    const oldMsgs = history.slice(0, history.length - MAX_KEEP);
    const keepMsgs = history.slice(-MAX_KEEP);
    if (!oldMsgs.length) return null;
    
    // Smart compression
    const compressed = await smartCompress(oldMsgs);
    
    // Save rolling summaries
    const rs = await kvGet('rolling_summaries') || [];
    rs.push({
      ts: Date.now(),
      date: new Date().toISOString(),
      summary: compressed ? compressed.summary : 'Obrolan lama',
      rolledCount: oldMsgs.length,
      keyFacts: compressed ? compressed.keyFacts : [],
      topics: compressed ? compressed.topics : [],
      decisions: compressed ? compressed.decisions : []
    });
    if (rs.length > 15) rs.splice(0, rs.length - 15);
    await kvPut('rolling_summaries', rs);
    
    // Extract key facts
    if (compressed && compressed.keyFacts.length) {
      const mem = await getCloudMemory('default');
      if (!mem.facts) mem.facts = [];
      compressed.keyFacts.forEach(function(f) {
        const dup = mem.facts.some(function(x) { return (x || '').toLowerCase().indexOf(f.substring(0, 30).toLowerCase()) !== -1; });
        if (!dup) mem.facts.push(f);
      });
      if (mem.facts.length > 60) mem.facts.splice(0, mem.facts.length - 60);
      await saveCloudMemory('default', mem);
    }
    
    // Trim history
    await kvPut('chat_history', keepMsgs);
    return compressed;
  } catch(e) { return null; }
}



