// --- JIWA: tren mood harian ---
// === MOOD-TREND UPGRADE: Anomaly Detection + Weekly Patterns + Correlation ===
async function updateMoodTrend(mood){
  try{
    const trend = await kvGet('mood_trend') || {history:[], daily:{}, weekly:{}, anomalies:[]};
    const today = new Date().toISOString().split('T')[0];
    const weekNum = Math.floor(Date.now() / (7*24*3600*1000));
    // Daily tracking
    if(!trend.daily[today]) trend.daily[today] = {};
    trend.daily[today][mood] = (trend.daily[today][mood] || 0) + 1;
    // Weekly aggregation
    const wKey = 'W' + weekNum;
    if(!trend.weekly) trend.weekly = {};
    if(!trend.weekly[wKey]) trend.weekly[wKey] = {};
    trend.weekly[wKey][mood] = (trend.weekly[wKey][mood] || 0) + 1;
    // History (keep last 500)
    trend.history.push({ mood: mood, ts: Date.now() });
    if(trend.history.length > 500) trend.history.splice(0, trend.history.length - 500);
    // Anomaly detection: count sudden spike in negative moods within 1 hour
    const recentHour = trend.history.filter(function(h){ return (Date.now() - h.ts) < 3600000; });
    const negCount = recentHour.filter(function(h){ return ['serius','khawatir','idle'].indexOf(h.mood) !== -1; }).length;
    if(negCount >= 4){
      const anomaly = {type:'negative_spike', count:negCount, ts:Date.now(), moods:recentHour.map(function(h){return h.mood;})};
      if(!trend.anomalies) trend.anomalies = [];
      trend.anomalies.push(anomaly);
      if(trend.anomalies.length > 20) trend.anomalies.splice(0, trend.anomalies.length - 20);
    }
    // Clean daily > 30 days
    const cutoff = Date.now() - 30*24*3600*1000;
    for(const d of Object.keys(trend.daily)){
      if(new Date(d).getTime() < cutoff) delete trend.daily[d];
    }
    await kvPut('mood_trend', trend);
  }catch(e){}
}

async function getMoodTrend(){
  try{
    const trend = await kvGet('mood_trend') || {history:[], daily:{}, weekly:{}, anomalies:[]};
    const today = new Date().toISOString().split('T')[0];
    const todayMoods = trend.daily[today] || {};
    const dominant = Object.entries(todayMoods).sort(function(a,b){return b[1]-a[1];})[0];
    // Weekly summary
    const weekNum = Math.floor(Date.now() / (7*24*3600*1000));
    const wKey = 'W' + weekNum;
    const weekMoods = (trend.weekly||{})[wKey] || {};
    const weekDominant = Object.entries(weekMoods).sort(function(a,b){return b[1]-a[1];})[0];
    // Mood stability score (lower variance = more stable)
    const recent7 = trend.history.slice(-50);
    const moodCounts = {};
    recent7.forEach(function(h){moodCounts[h.mood]=(moodCounts[h.mood]||0)+1;});
    const vals = Object.values(moodCounts);
    const avg = vals.reduce(function(a,b){return a+b;},0) / (vals.length||1);
    const variance = vals.reduce(function(a,v){return a+(v-avg)*(v-avg);},0) / (vals.length||1);
    const stability = Math.max(0, Math.round(100 - variance * 5));
    // Anomalies
    const recentAnomalies = (trend.anomalies||[]).slice(-3).reverse();
    return {
      today_dominant: dominant ? dominant[0] : null,
      today_count: Object.values(todayMoods).reduce(function(a,b){return a+b;}, 0),
      today_breakdown: todayMoods,
      week_dominant: weekDominant ? weekDominant[0] : null,
      week_breakdown: weekMoods,
      stability: stability,
      total_entries: trend.history.length,
      anomalies: recentAnomalies,
      total_days_tracked: Object.keys(trend.daily).length
    };
  }catch(e){ return {today_dominant:null, today_count:0, today_breakdown:{}, week_dominant:null, week_breakdown:{}, stability:50, total_entries:0, anomalies:[], total_days_tracked:0}; }
}

