// Learn opinion from conversation (when user shares their opinion)
async function learnUserOpinion(text){
  try{
    const low = String(text).toLowerCase();
    const patterns = [
      /(?:gw|gue|gue) (?:suka|favorit|penasaran|demen|milih|pilih|prefer) (.+?)(?:\.|,|!|\?|$)/i,
      /(?:menurut gw|kayaknya|rasanya) (.+?)(?:\.|!|\?|$)/i,
      /(?:bagus|jelek|oke|mantap|parah) banget (.+?)(?:\.|!|\?|$)/i
    ];
    for(const p of patterns){
      const m = low.match(p);
      if(m && m[1] && m[1].length > 3){
        const topic = m[1].trim().substring(0, 40);
        const opinion = String(text).substring(0, 200);
        // Store user's opinion for reference
        const userOp = await kvGet('user_opini') || {};
        userOp[topic] = opinion;
        await kvPut('user_opini', userOp);
        return true;
      }
    }
  }catch(e){}
  return false;
}

