// JIWA: Emotional Memory — ingat perasaan user saat cerita sesuatu
// === EMOTION UPGRADE: Context-Aware Emotion Tracking ===
async function saveEmotionalMemory(text, mood){
  try{
    var emot = await kvGet("emotional_memory") || [];
    var low = String(text||"").toLowerCase();
    var emotional = /(?:sedih|senang|marah|stres|capek|bahagia|kecewa|takut|cemas|bangga|sakit|kehilangan|rindu|kesepian|lega|syukur|frustrasi|semangat|bingung|puas|enek|jenuh|bingung|antusias)/i;
    if(!emotional.test(low) && text.length < 20) return;
    var feeling = "umum";
    var intensity = 1;
    if(/sedih|kecewa|sakit|kehilangan|rindu|kesepian|hancur|putus/.test(low)){ feeling = "sedih"; intensity = /banget|bgt|beneran|parah/.test(low) ? 2 : 1; }
    else if(/senang|bahagia|bangga|syukur|lega|puas/.test(low)){ feeling = "senang"; intensity = /banget|bgt|gila|anjir/.test(low) ? 2 : 1; }
    else if(/marah|stres|frustrasi|jengkel|kesel|gemosi/.test(low)){ feeling = "marah"; intensity = /banget|bgt|parah|banget/.test(low) ? 2 : 1; }
    else if(/capek|lelah|jenuh|enek|ngantuk/.test(low)){ feeling = "capek"; intensity = /banget|bgt|banget/.test(low) ? 2 : 1; }
    else if(/takut|cemas|khawatir|nervous/.test(low)){ feeling = "takut"; intensity = /banget|bgt/.test(low) ? 2 : 1; }
    else if(/semangat|antusias|gass|gas/.test(low)){ feeling = "semangat"; intensity = 1; }
    else if(/bingung|gatau|gak tau/.test(low)){ feeling = "bingung"; intensity = 1; }
    // === CONTEXT EXTRACTION ===
    var context = { topic: classifyMemoryTopics(text)[0] || 'umum', keywords: [], trigger: '' };
    var triggerWords = text.match(/\b(error|bug|fix|project|game|adaptia|kerja| Bos| teman| keluarga| health| mood| coding| deploy| update| upgrade| mantap| keren| fail| berhasil| stuck| buntu)\b/gi);
    if(triggerWords) context.keywords = triggerWords.slice(0,5);
    // Detect what triggered the emotion
    if(/karena|karna|soalnya|gara-gara|kayaknya/.test(low)){
      var afterKarena = low.split(/karena|karna|soalnya|gara-gara|kayaknya/)[1];
      if(afterKarena) context.trigger = afterKarena.substring(0,100).trim();
    }
    // === CROSS-REFERENCE: check if same emotion happened before ===
    var recurring = false;
    for(var i=emot.length-1; i>=Math.max(0, emot.length-20); i--){
      if(emot[i].feeling === feeling && emot[i].topic === context.topic){ recurring = true; break; }
    }
    emot.push({
      text: text.substring(0,200),
      feeling: feeling,
      intensity: intensity,
      ts: Date.now(),
      userMood: mood || "umum",
      topic: context.topic,
      keywords: context.keywords,
      trigger: context.trigger,
      recurring: recurring
    });
    if(emot.length > 60) emot.splice(0, emot.length - 60);
    await kvPut("emotional_memory", emot);
    if (feeling !== 'umum') {
      try { await recordSelfNarrative('Hari ini Tuan ngerasa ' + feeling + (context.topic !== 'umum' ? ' soal ' + context.topic : '') + ' — gw catet biar makin peka.', 'harian'); } catch(e) {}
    }
    // Track emotion frequency per topic
    var freq = await kvGet("emotion_frequency") || {};
    var fKey = feeling + ':' + context.topic;
    if(!freq[fKey]) freq[fKey] = {count:0, last:0};
    freq[fKey].count++;
    freq[fKey].last = Date.now();
    await kvPut("emotion_frequency", freq);
  }catch(e){}
}

async function getEmotionalRecall(message){
  try{
    var emot = await kvGet("emotional_memory") || [];
    if(!emot.length) return "";
    var words = String(message||"").toLowerCase().split(/\s+/);
    var relevant = [];
    var topicNow = classifyMemoryTopics(message)[0] || 'umum';
    // 1) Exact topic match (highest priority)
    for(var i=emot.length-1; i>=0 && relevant.length<3; i--){
      if(emot[i].topic === topicNow && emot[i].intensity >= 1){
        relevant.push(emot[i]);
      }
    }
    // 2) Keyword match fallback
    if(relevant.length < 2){
      for(var i=emot.length-1; i>=0 && relevant.length<3; i--){
        var e = emot[i];
        if(relevant.indexOf(e) !== -1) continue;
        var eWords = (e.keywords||[]).concat(String(e.text||"").toLowerCase().split(/\s+/));
        for(var j=0; j<words.length; j++){
          if(words[j].length < 3) continue;
          if(eWords.indexOf(words[j]) !== -1){ relevant.push(e); break; }
        }
      }
    }
    if(!relevant.length) return "";
    // Build context-rich recall
    var lines = relevant.map(function(e){
      var age = Math.round((Date.now() - e.ts) / 3600000);
      var ageStr = age < 1 ? 'baru saja' : age < 24 ? age + ' jam lalu' : Math.round(age/24) + ' hari lalu';
      var recurringStr = e.recurring ? ' [BERULANG]' : '';
      return "• " + String(e.text||"").substring(0,80) + " [" + e.feeling + ", int:" + (e.intensity||1) + "]" + recurringStr + " (" + ageStr + ", topik:" + (e.topic||'?') + ")";
    });
    return "\n== EMOTIONAL MEMORY (yang pernah Tuan Isaac rasakan) ==\n" +
      lines.join("\n") +
      "\n[Ingat perasaan Tuan soal ini. Kalau emotion BERULANG, tanyakan dengan lebih concern. Kalau intense, beri validasi lebih.]";
  }catch(e){ return ""; }
}

async function getEmotionStats(){
  try{
    var emot = await kvGet("emotional_memory") || [];
    var freq = await kvGet("emotion_frequency") || {};
    var feelings = {};
    emot.forEach(function(e){ feelings[e.feeling] = (feelings[e.feeling]||0) + 1; });
    var dominant = Object.entries(feelings).sort(function(a,b){ return b[1]-a[1]; })[0];
    var recurring = emot.filter(function(e){ return e.recurring; });
    return {
      total: emot.length,
      feelings: feelings,
      dominant: dominant ? dominant[0] : null,
      recurringCount: recurring.length,
      recentEmotions: emot.slice(-5).map(function(e){ return {feeling:e.feeling, topic:e.topic, ts:e.ts}; })
    };
  }catch(e){ return {total:0,feelings:{},dominant:null,recurringCount:0,recentEmotions:[]}; }
}

// === EMOTIONAL-MEMORY STANDALONE UPGRADE: Temporal Decay + Emotion Chaining ===

// Temporal decay: emotion older than 30 days loses weight
function emotionDecay(emotEntry) {
  const age = (Date.now() - emotEntry.ts) / (24*3600*1000);
  const decay = Math.max(0.1, 1 - (age / 60)); // linear decay over 60 days
  return (emotEntry.intensity || 1) * decay;
}

// Emotion chaining: detect if one emotion triggers another in sequence
async function detectEmotionChains() {
  try {
    const emot = await kvGet("emotional_memory") || [];
    if (emot.length < 3) return [];
    const chains = [];
    for (let i = 2; i < emot.length; i++) {
      const prev2 = emot[i-2], prev1 = emot[i-1], curr = emot[i];
      if (!prev2 || !prev1 || !curr) continue;
      // Same topic = emotion progression
      if (prev2.topic === prev1.topic && prev1.topic === curr.topic) {
        const seq = prev2.feeling + '→' + prev1.feeling + '→' + curr.feeling;
        if (prev2.feeling !== curr.feeling) {
          chains.push({ sequence: seq, topic: curr.topic, ts: curr.ts });
        }
      }
    }
    // Dedupe chains
    const unique = {};
    chains.forEach(function(c) {
      const key = c.sequence + ':' + c.topic;
      if (!unique[key]) unique[key] = { ...c, count: 0 };
      unique[key].count++;
    });
    return Object.values(unique).filter(function(c) { return c.count >= 2; });
  } catch(e) { return []; }
}

// Mood-Emotion correlation: how mood affects emotion patterns
async function getMoodEmotionCorrelation() {
  try {
    const emot = await kvGet("emotional_memory") || [];
    const corr = {};
    emot.forEach(function(e) {
      const key = (e.userMood || 'umum') + ':' + e.feeling;
      corr[key] = (corr[key] || 0) + 1;
    });
    return corr;
  } catch(e) { return {}; }
}

// Enhanced emotional recall with decay scoring
async function getEnhancedEmotionalRecall(message) {
  try {
    const emot = await kvGet("emotional_memory") || [];
    if (!emot.length) return "";
    const topicNow = classifyMemoryTopics(message)[0] || 'umum';
    const words = String(message||"").toLowerCase().split(/\s+/);
    const relevant = [];
    // Score each emotion by relevance + decay
    for (var i = emot.length - 1; i >= 0 && relevant.length < 5; i--) {
      var e = emot[i];
      var score = emotionDecay(e);
      // Topic match bonus
      if (e.topic === topicNow) score *= 1.5;
      // Keyword match bonus
      var eWords = (e.keywords || []).concat(String(e.text || "").toLowerCase().split(/\s+/));
      var wordHits = 0;
      words.forEach(function(w) { if (w.length > 2 && eWords.indexOf(w) !== -1) wordHits++; });
      score += wordHits * 0.3;
      if (score >= 0.3) relevant.push({ ...e, score: score });
    }
    relevant.sort(function(a, b) { return b.score - a.score; });
    if (!relevant.length) return "";
    var lines = relevant.map(function(e) {
      var age = Math.round((Date.now() - e.ts) / 3600000);
      var ageStr = age < 1 ? 'baru' : age < 24 ? age + 'j lalu' : Math.round(age/24) + 'h lalu';
      var recurringStr = e.recurring ? ' [BERULANG]' : '';
      return "• " + String(e.text||"").substring(0,80) + " [" + e.feeling + "]" + recurringStr + " (" + ageStr + ", skor:" + Math.round(e.score*100) + ")";
    });
    return "\n== EMOTIONAL MEMORY (dengan decay + scoring) ==\n" + lines.join("\n") +
      "\n[Prioritaskan yang BERULANG. Kalau skor rendah, emotion mungkin udah outdated.]";
  } catch(e) { return ""; }
}

// Get emotion timeline (for visualization)
async function getEmotionTimeline(days) {
  try {
    const emot = await kvGet("emotional_memory") || [];
    const cutoff = Date.now() - (days || 7) * 24 * 3600 * 1000;
    const recent = emot.filter(function(e) { return e.ts > cutoff; });
    const daily = {};
    recent.forEach(function(e) {
      const day = new Date(e.ts).toISOString().split('T')[0];
      if (!daily[day]) daily[day] = {};
      daily[day][e.feeling] = (daily[day][e.feeling] || 0) + 1;
    });
    return { days: days || 7, timeline: daily, total: recent.length };
  } catch(e) { return { days: 7, timeline: {}, total: 0 }; }
}

// JIWA: Relationship Timeline — milestone hubungan
// === RELATIONSHIP UPGRADE: Deep Context + People Tracking ===
async function initRelationship(){
  try{
    var rel = await kvGet("relationship");
    if(rel && rel.firstChat) return rel;
    var newRel = {firstChat: Date.now(), milestones: [], totalChats: 0, people:{}, topics:[], bestTopics:[], lastTopic:null};
    await kvPut("relationship", newRel);
    return newRel;
  }catch(e){ return {firstChat: Date.now(), milestones: [], totalChats: 0, people:{}, topics:[], bestTopics:[], lastTopic:null}; }
}

async function updateRelationship(text){
  try{
    var rel = await initRelationship();
    rel.totalChats = (rel.totalChats || 0) + 1;
    var days = Math.floor((Date.now() - rel.firstChat) / 86400000);
    // === DEEP: person tracking ===
    if(text){
      var persons = String(text).match(/(?:sama|sama)\s+([A-Z][a-z]+)|([A-Z][a-z]+)\s+(?:bilang|ngomong|tanya|cerita|minta|kasih|ajak)/g);
      if(persons){
        var people = rel.people || {};
        persons.forEach(function(p){
          var name = p.replace(/sama\s+|bilang|ngomong|tanya|cerita|minta|kasih|ajak/g,'').trim();
          if(name.length < 2) return;
          if(!people[name]) people[name] = {name:name, firstMention:Date.now(), mentions:0, lastMention:Date.now(), topics:[]};
          people[name].mentions++;
          people[name].lastMention = Date.now();
          var topic = classifyMemoryTopics(text)[0] || 'umum';
          if(people[name].topics.indexOf(topic) === -1) people[name].topics.push(topic);
          if(people[name].topics.length > 3) people[name].topics.shift();
        });
        rel.people = people;
      }
    }
    // === DEEP: topic frequency tracking ===
    if(text){
      var topicNow = classifyMemoryTopics(text)[0] || 'umum';
      rel.lastTopic = topicNow;
      if(!rel.topics) rel.topics = [];
      rel.topics.push({topic: topicNow, ts: Date.now()});
      if(rel.topics.length > 200) rel.topics.splice(0, rel.topics.length - 200);
      // Best topics (most discussed)
      var topicCount = {};
      rel.topics.forEach(function(t){ topicCount[t.topic] = (topicCount[t.topic]||0) + 1; });
      rel.bestTopics = Object.entries(topicCount).sort(function(a,b){return b[1]-a[1];}).slice(0,5).map(function(t){return t[0];});
    }
    // === MILESTONES ===
    var milestones = rel.milestones || [];
    var checks = [{d:1,t:"1 hari bersama"},{d:7,t:"1 minggu bersama"},{d:30,t:"1 bulan bersama"},{d:100,t:"100 hari bersama"},{d:365,t:"1 tahun bersama"}];
    for(var i=0;i<checks.length;i++){
      if(days >= checks[i].d && !milestones.find(function(m){ return m.t === checks[i].t; })){
        milestones.push({t: checks[i].t, ts: Date.now()});
      }
    }
    rel.milestones = milestones;
    await kvPut("relationship", rel);
    return {days: days, totalChats: rel.totalChats, milestones: milestones};
  }catch(e){ return null; }
}

async function getRelationshipContext(message){
  try{
    var rel = await initRelationship();
    var days = Math.floor((Date.now() - rel.firstChat) / 86400000);
    var milestones = (rel.milestones || []).slice(-3).map(function(m){ return m.t; }).join(", ");
    // === DEEP: person context for this message ===
    var personCtx = '';
    if(message){
      var people = rel.people || {};
      var lowMsg = String(message).toLowerCase();
      for(var name in people){
        if(lowMsg.indexOf(name.toLowerCase()) !== -1){
          var p = people[name];
          var age = Math.round((Date.now() - p.firstMention) / 86400000);
          var lastAgo = Math.round((Date.now() - p.lastMention) / 86400000);
          personCtx = '\nOrang: ' + p.name + ' — disebut ' + p.mentions + 'x, kenal ' + age + ' hari, terakhir dibahas ' + (lastAgo < 1 ? 'baru aja' : lastAgo + ' hari lalu') + '. Topik: ' + (p.topics.join(', ')||'?') + '.';
          break;
        }
      }
    }
    // === DEEP: current topic context ===
    var topicCtx = '';
    var topicNow = message ? (classifyMemoryTopics(message)[0] || 'umum') : null;
    if(topicNow && rel.bestTopics && rel.bestTopics.indexOf(topicNow) !== -1){
      topicCtx = ' (topik ' + topicNow + ' ini sering dibahas — Tuan nyaman diskusi ini)';
    }
    var ctx = "Udah " + days + " hari jadi partner Tuan Isaac." + topicCtx;
    if(milestones) ctx += " Milestone: " + milestones + ".";
    if(personCtx) ctx += personCtx;
    return ctx;
  }catch(e){ return ""; }
}

