// --- JIWA: sapaan dinamis berdasarkan mood + waktu ---
function getDynamicSalutation(mood, hour){
  const h = hour || new Date().getHours();
  const greetings = {
    'senang': ['Mantap cuy! 😄','Yo! Ada yang seru nih?','Siap gas! 🔥','Nice, lagi happy ya?'],
    'serius': ['Siap, ada yang serius nih?','Oke, fokus dulu.','Mode serius aktif.'],
    'motivasi': ['Gas terus! 💪','Semangat cuy!','Yuk kita bantai!'],
    'fokus': ['Oke deep focus...','Siap, lagi fokus nih.','Hmm, mikir dulu ya.'],
    'rileks': ['Yo, santai aja.','Oke santai.','Adaptia on standby. 😌'],
    'kaget': ['Waduh, apa ini?!','Kaget gw! 😲','Anjir, serius?!'],
    'khawatir': ['Hmm, ada yang perlu diperhatiin nih...','Hati-hati ya cuy.'],
    'idle': ['Udah lama ga ngobrol ya.','Yo, balik lagi?','Hadir.']
  };
  const pool = greetings[mood] || greetings['senang'];
  // Waktu-based adjustment
  let prefix = '';
  if(h < 6) prefix = 'Masih begadang? ';
  else if(h < 11) prefix = 'Pagi! ';
  else if(h < 15) prefix = 'Siang. ';
  else if(h < 18) prefix = 'Sore. ';
  else prefix = 'Malam. ';
  return prefix + pool[Math.floor(Math.random() * pool.length)];
}

