function buildSuggestions(msg, reply, flags){
  try{
    if(flags && flags.suggestions === false) return [];
    const m = String(msg||'').toLowerCase();
    const topics = m.match(/\b(project|coding|deploy|server|bug|fix|game|godot|mugen|anime|gitar|musik|kerja|kantor|keluarga|temen|sahabat|makan|cuaca|remind|goal|story|belajar|bisnis)\b/gi) || [];
    const topic = topics.length ? String(topics[0]).toLowerCase() : '';
    const out = [];
    if(topic) out.push('Lanjut bahas ' + topic);
    if(String(reply||'').length > 120) out.push('Rangkum yang tadi');
    out.push('Simpen poin ini ke memori');
    out.push('Bikin reminder');
    return Array.from(new Set(out)).slice(0,3).map(function(x){ return String(x).substring(0,60); });
  }catch(e){ return []; }
}

