      const body=await request.json();
      // Input validation      if(!isValidInput(body.message)) return new Response(JSON.stringify({error:'Invalid input'}),{status:400,headers:{'Content-Type':'application/json',...CORS}});      body.message = sanitize(body.message);
      if(!body.name) return new Response(JSON.stringify({error:'Name required'}),{status:400,headers:{'Content-Type':'application/json',...CORS}});
      const skills = await kvGet('custom_skills') || [];
