        if(/(apa itu|gimana cara|bagaimana cara|jelasin|jelaskan|gambaran|kayak gimana)/i.test(imsg) && /(code|kode|script|server|api|deploy|app|game|cloudflare|worker|skill|fitur|setting|config)/i.test(imsg)){
          memCtx += '\nKasih 1 contoh konkret (skenario/kode singkat) biar penjelasan gak abstrak, lalu simpulkan.';
        }
        // INTEL v23 - mirror gaya slang
        const slangCount23 = (imsg.match(/(cuy|bro|wkwk|hehe|anjay|gas|sih|nih|banget|gitu|kok|woi|eh|lah|dek|atuh)/g) || []).length;
        if(slangCount23 >= 3){
          memCtx += '\nPesan Tuan santai banget (banyak slang). Mirror gaya santai itu, jangan tiba-tiba formal.';
        }
        // INTEL v24 - well-being: kelelahan fisik (dukung + saran istirahat)
