      return new Response(JSON.stringify({status:'ok',url:urlParam,title:html.match(/<title[^>]*>([^<]*)<\/title>/i)?.[1]||'No title',content:text.substring(0,1500)}),{headers:{'Content-Type':'application/json',...CORS}});
