async function generateDailyDigest() {
  try {
    const history = await kvGet('chat_history') || [];
    const today = new Date().toISOString().split('T')[0];
    const todayChats = history.filter(function(h) { return h.ts && new Date(h.ts).toISOString().split('T')[0] === today; });
    const mem = await getCloudMemory('default');
    const identity = await getIdentity();
    
    if (todayChats.length < 2) return null;
    
    // Topic analysis
    const topicCount = {};
    todayChats.forEach(function(h) {
      const t = classifyMemoryTopics(h.text || '')[0] || 'umum';
      topicCount[t] = (topicCount[t] || 0) + 1;
    });
    const topTopics = Object.entries(topicCount).sort(function(a, b) { return b[1] - a[1]; }).slice(0, 5);
    
    // Mood flow
    const mood = identity.emotionState?.mood || 'kalem';
    
    // Quality
    const q = await scoreConversationQuality(todayChats);
    
    // Duration
    const duration = todayChats.length > 1 ? Math.round((new Date(todayChats[todayChats.length - 1].ts) - new Date(todayChats[0].ts)) / 60000) : 0;
    
    // Goals progress
    const activeGoals = (mem.goals || []).filter(function(g) { return !g.done; });
    
    // Key moments
    const longMsgs = todayChats.filter(function(h) { return String(h.text || '').length > 40; });
    const keyMoment = longMsgs.length ? String(longMsgs[Math.floor(Math.random() * longMsgs.length)].text || '').substring(0, 60) : null;
    
    // Build digest
    let digest = '📊 *ADAPTIA DAILY DIGEST*\n';
    digest += '📅 ' + today + '\n\n';
    digest += '💬 Chat: ' + todayChats.length + ' pesan (' + duration + ' menit)\n';
    digest += '🎯 Topik: ' + topTopics.map(function(t) { return t[0]; }).join(', ') + '\n';
    digest += '😊 Mood: ' + mood + '\n';
    if (q) digest += '⭐ Quality: ' + q.score + '/100\n';
    digest += '🧠 Pengetahuan: ' + (mem.facts || []).length + ' fakta\n';
    if (activeGoals.length) digest += '📋 Goals aktif: ' + activeGoals.length + '\n';
    if (keyMoment) digest += '\n💡 Momen: "' + keyMoment + '"\n';
    digest += '\n_ Terus semangat Tuan Isaac! 💪_';
    
    return digest;
  } catch(e) { return null; }
}

