async function scoreConversationQuality(sessionHistory) {
  try {
    if (!sessionHistory || sessionHistory.length < 2) return null;
    const metrics = {
      length: sessionHistory.length,
      avgMsgLength: 0,
      userEngagement: 0,
      topicDiversity: 0,
      questionRate: 0,
      sentimentShift: 0,
      responseLatency: 0
    };
    let totalLen = 0, questions = 0, topics = {}, lastTs = 0, latencies = [];
    sessionHistory.forEach(function(h) {
      totalLen += String(h.text || '').length;
      if (/\?/.test(h.text)) questions++;
      const t = classifyMemoryTopics(h.text || '')[0] || 'umum';
      topics[t] = (topics[t] || 0) + 1;
      if (lastTs && h.ts) latencies.push(h.ts - lastTs);
      lastTs = h.ts || 0;
    });
    metrics.avgMsgLength = Math.round(totalLen / sessionHistory.length);
    metrics.userEngagement = Math.min(100, Math.round((sessionHistory.length / 10) * 100));
    metrics.topicDiversity = Object.keys(topics).length;
    metrics.questionRate = Math.round((questions / sessionHistory.length) * 100);
    if (latencies.length) metrics.responseLatency = Math.round(latencies.reduce(function(a, b) { return a + b; }, 0) / latencies.length / 1000);
    // Quality score: 0-100
    const qScore = Math.min(100, Math.round(
      (metrics.userEngagement * 0.3) +
      (metrics.topicDiversity * 15) +
      (metrics.questionRate * 0.2) +
      (metrics.avgMsgLength > 20 ? 20 : metrics.avgMsgLength) +
      (metrics.length > 5 ? 15 : metrics.length * 3)
    ));
    return { score: qScore, metrics: metrics, ts: Date.now() };
  } catch(e) { return null; }
}

async function saveSessionQuality(score) {
  try {
    if (!score) return;
    const log = await kvGet('quality_log') || [];
    log.push(score);
    if (log.length > 50) log.splice(0, log.length - 50);
    await kvPut('quality_log', log);
    // Update average quality
    const avg = log.reduce(function(a, l) { return a + l.score; }, 0) / log.length;
    await kvPut('quality_avg', Math.round(avg));
  } catch(e) {}
}

async function getQualityStats() {
  try {
    const log = await kvGet('quality_log') || [];
    const avg = log.length ? Math.round(log.reduce(function(a, l) { return a + l.score; }, 0) / log.length) : 0;
    const best = log.length ? Math.max.apply(null, log.map(function(l) { return l.score; })) : 0;
    const worst = log.length ? Math.min.apply(null, log.map(function(l) { return l.score; })) : 0;
    return { avg: avg, best: best, worst: worst, total: log.length, recent: log.slice(-5).reverse() };
  } catch(e) { return { avg: 0, best: 0, worst: 0, total: 0, recent: [] }; }
}

