// ---------- VOICE SETTINGS ----------
async function getVoiceSettings(){
  try{
    const s = await kvGet('voice_settings');
    if(s && s.rate != null) return s;
  }catch(e){}
  return { rate:1.0, pitch:1.0, voiceName:'', autoRead:false, lang:'id-ID', version:1 };
}
async function saveVoiceSettings(data){
  const cur = await getVoiceSettings();
  if(data.rate != null) cur.rate = Math.max(0.5, Math.min(2.0, parseFloat(data.rate)||1.0));
  if(data.pitch != null) cur.pitch = Math.max(0.5, Math.min(2.0, parseFloat(data.pitch)||1.0));
  if(data.voiceName !== undefined) cur.voiceName = String(data.voiceName).substring(0,100);
  if(data.autoRead !== undefined) cur.autoRead = !!data.autoRead;
  if(data.lang !== undefined) cur.lang = String(data.lang).substring(0,10);
  cur.updated = Date.now();
  await kvPut('voice_settings', cur);
  return cur;
}

// ---------- CODE REVIEW ----------
async function codeReview(code, language){
  try{
    if(!code || code.length < 10) return null;
    const prompt = 'Kamu reviewer kode senior. Review kode ' + language + ' ini:\n\n' + code.substring(0,2500) +
      '\n\nFormat jawaban JSON:\n{"bugs":[{"line":"...","issue":"...","fix":"..."}],' +
      '"improvements":["..."],"security":["..."],"complexity":"low|medium|high","summary":"..."}\n' +
      'Maks 3 bug, 3 improvements, 2 security. Bahasa Gaul Indonesia.';
    const ai = await smartAIReply([{role:'user',content:prompt}], 700);
    if(!ai) return null;
    // Try parse JSON
    try{
      const match = ai.match(/\{[\s\S]*\}/);
      if(match) return JSON.parse(match[0]);
    }catch(e){}
    return { summary: ai.substring(0,300), raw: true };
  }catch(e){ return null; }
}

