// ---------- 1. URGENCY & PRIORITY ROUTING ----------
function classifyUrgency(message) {
  const t = String(message || '').toLowerCase();
  const urgentWords = ['darurat', 'urgent', 'error', 'gabisa', 'rusak', 'crash', 'sekarang', 'cepetan', 'cepat', 'langsung', 'penting', 'bahaya', 'mendesak', 'tolong banget', 'help fast', 'asap', 'gawat'];
  const relaxWords = ['wkwk', 'haha', 'hehe', 'santai', 'ngobrol', 'cerita', 'lucu', 'chill', 'bosen', 'gas main'];
  let score = 0, reasons = [];
  urgentWords.forEach(function(w) { if (t.indexOf(w) !== -1) { score += 2; reasons.push('urgent:' + w); } });
  relaxWords.forEach(function(w) { if (t.indexOf(w) !== -1) { score -= 1; reasons.push('relax:' + w); } });
  if (t.endsWith('!') || /!{2,}/.test(t)) { score += 1; reasons.push('exclaim'); }
  if (!t || t.length < 3) score = 0;
  let level = 'normal';
  if (score >= 3) level = 'urgent';
  else if (score <= -1) level = 'santai';
  return { level, score, reasons: reasons.slice(0, 3), ts: Date.now() };
}

function getUrgencyContext(message) {
  try {
    const u = classifyUrgency(message);
    if (u.level === 'urgent') return '\n== PRIORITAS ==\nPesan Tuan URGENT. Jawaban singkat, to the point, langsung solusi, jangan basa-basi, minim emoji. Fokus: bantu sekarang.';
    if (u.level === 'santai') return '\n== PRIORITAS ==\nPesan santai. Boleh jawaban hangat, sedikit candaan, emoji secukupnya.';
    return '';
  } catch (e) { return ''; }
}

// ---------- 2. NLP TIME PARSER (WIB-aware) ----------
function parseTimeExpression(text) {
  try {
    const t = String(text || '').toLowerCase();
    const out = { found: false };
    // WIB = UTC+7. Wall-clock "now" di Asia/Jakarta:
    const nowWIB = new Date(Date.now() + 7 * 3600000);
    const now = new Date();
    // Bangun tanggal target dari komponen WIB: "hari ini + dayOffset pukul HH:MM WIB"
    function wibTarget(dayOffset, hour, min) {
      const d = new Date(Date.UTC(nowWIB.getUTCFullYear(), nowWIB.getUTCMonth(), nowWIB.getUTCDate() + dayOffset, hour, min, 0, 0));
      return new Date(d.getTime() - 7 * 3600000);
    }
    // Pattern: "jam HH" or "jam HH:MM"
    let m = t.match(/(?:jam|pukul)\s+(\d{1,2})(?::(\d{2}))?/);
    let hour = null, min = 0;
    if (m) { hour = parseInt(m[1]); min = m[2] ? parseInt(m[2]) : 0; }
    // Day offset
    let dayOffset = 0;
    if (/besok lusa/.test(t)) dayOffset = 2;
    else if (/lusa/.test(t)) dayOffset = 2;
    else if (/besok/.test(t)) dayOffset = 1;
    else if (/hari ini|sekarang/.test(t)) dayOffset = 0;
    else if (/(\d+)\s+hari lagi/.test(t)) dayOffset = parseInt(t.match(/(\d+)\s+hari lagi/)[1]);
    // Weekday
    const dayMap = { 'senin': 1, 'selasa': 2, 'rabu': 3, 'kamis': 4, 'jumat': 5, 'sabtu': 6, 'minggu': 0 };
    let targetDay = null;
    for (const d in dayMap) { if (t.indexOf(d + ' depan') !== -1) { targetDay = dayMap[d]; break; } }
    // Prioritas: weekday > besok/lusa/hari-ini > jam saja (default today)
    if (!out.found && targetDay !== null) {
      const daysUntil = (targetDay - nowWIB.getUTCDay() + 7) % 7 || 7;
      const h = hour !== null ? hour : 9;
      const d = wibTarget(daysUntil, h, min);
      out.found = true; out.type = 'at'; out.date = d.toISOString(); out.label = d.toLocaleString('id-ID', { timeZone: 'Asia/Jakarta', weekday: 'long', day: 'numeric', month: 'long', hour: '2-digit', minute: '2-digit' });
    } else if (!out.found && hour !== null) {
      let d = wibTarget(dayOffset, hour, min);
      if (d < now) d = wibTarget(dayOffset + 1, hour, min);
      out.found = true; out.type = 'at'; out.date = d.toISOString(); out.label = d.toLocaleString('id-ID', { timeZone: 'Asia/Jakarta', weekday: 'long', day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' });
    } else if (!out.found && /besok/.test(t)) {
      const h = hour !== null ? hour : 9;
      const d = wibTarget(1, h, min);
      out.found = true; out.type = 'at'; out.date = d.toISOString(); out.label = 'besok ' + d.toLocaleDateString('id-ID', { timeZone: 'Asia/Jakarta', weekday: 'long', day: 'numeric' });
    }
    return out;
  } catch (e) { return { found: false }; }
}

async function autoSaveReminderFromChat(message) {
  try {
    if (!message) return null;
    const low = String(message).toLowerCase();
    if (!/(ingetin|reminder|jangan lupa|tolong ingatkan)/.test(low)) return null;
    const parsed = parseTimeExpression(low);
    if (!parsed.found) return null;
    // Text after "ingetin/reminder/jangan lupa"
    const textMatch = low.match(/(?:ingetin|reminder|jangan lupa|tolong ingatkan)\s+(.+)/);
    const reminderText = textMatch ? textMatch[1].substring(0, 100) : message.substring(0, 100);
    const reminders = (await kvGet('reminders_default')) || [];
    reminders.push({ time: parsed.date, text: reminderText, created: new Date().toISOString(), sent: false, parsed: true });
    await kvPut('reminders_default', reminders);
    return { time: parsed.date, label: parsed.label, text: reminderText };
  } catch (e) { return null; }
}

// ---------- 3. GOAL AUTO-PROGRESS ----------
async function trackGoalProgress(text) {
  try {
    if (!text) return null;
    const mem = await getCloudMemory('default');
    const goals = (mem.goals || []).filter(function(g) { return g && !g.done; });
    if (!goals.length) return null;
    const t = String(text).toLowerCase();
    // Detect progress/completion statements
    const doneMatch = t.match(/(?:selesai|kelar|beres|done|tuntas|udah jadi|jadi juga|fix)\s+(?:nge|ng)?(?:\w+\s*){0,3}(?:goal|project|tugas|game|app|website|fitur)?/);
    const progMatch = t.match(/(?:progress|progres|udah\s+\d+%|baru\s+\d+%|setengah|maju)\s+(\S+)/);
    if (doneMatch) {
      // Mark most likely goal as having progress (completion signal)
      const g = goals[0];
      if (!g.progress) g.progress = [];
      g.progress.push({ text: String(text).substring(0, 100), ts: Date.now(), type: 'progress' });
      if (g.progress.length > 20) g.progress = g.progress.slice(-20);
      await saveCloudMemory('default', mem);
      return { goal: g.text, type: 'update', status: 'active' };
    }
    if (progMatch) {
      const g = goals[0];
      if (!g.progress) g.progress = [];
      g.progress.push({ text: String(text).substring(0, 100), ts: Date.now(), type: 'progress' });
      if (g.progress.length > 20) g.progress = g.progress.slice(-20);
      await saveCloudMemory('default', mem);
      return { goal: g.text, type: 'progress', status: 'active' };
    }
    return null;
  } catch (e) { return null; }
}

// ---------- 4. WEEKLY EMOTION REPORT ----------
async function generateWeeklyEmotionReport() {
  try {
    const trend = await kvGet('mood_trend') || { history: [], daily: {} };
    const emot = await kvGet('emotional_memory') || [];
    const rel = await initRelationship();
    const weekAgo = Date.now() - 7 * 24 * 3600 * 1000;
    const weekEntries = trend.history.filter(function(h) { return h.ts > weekAgo; });
    const weekEmotions = emot.filter(function(e) { return e.ts > weekAgo; });
    const moodCounts = {};
    weekEntries.forEach(function(h) { moodCounts[h.mood] = (moodCounts[h.mood] || 0) + 1; });
    const topMood = Object.entries(moodCounts).sort(function(a, b) { return b[1] - a[1]; })[0];
    const feelingCounts = {};
    weekEmotions.forEach(function(e) { feelingCounts[e.feeling] = (feelingCounts[e.feeling] || 0) + 1; });
    const topFeeling = Object.entries(feelingCounts).sort(function(a, b) { return b[1] - a[1]; })[0];
    const moodLabel = { senang: 'happy', serius: 'serius', motivasi: 'semangat', khawatir: 'khawatir', fokus: 'fokus', rileks: 'santai', kaget: 'kaget', idle: 'istirahat' };
    let report = '📊 *WEEKLY EMOTION REPORT*\n';
    report += '📅 ' + new Date().toISOString().split('T')[0] + '\n\n';
    report += '😊 Mood dominan minggu ini: ' + (topMood ? (moodLabel[topMood[0]] || topMood[0]) + ' (' + topMood[1] + 'x)' : 'belum cukup data') + '\n';
    report += '💭 Perasaan dominan: ' + (topFeeling ? topFeeling[0] + ' (' + topFeeling[1] + 'x)' : 'belum cukup data') + '\n';
    report += '💬 Total interaksi: ' + weekEntries.length + '\n';
    report += '❤️ ' + (rel.totalChats || 0) + ' chats total bersama Tuan Isaac\n';
    if (topFeeling && (topFeeling[0] === 'sedih' || topFeeling[0] === 'marah' || topFeeling[0] === 'capek')) {
      report += '\n⚠️ *Catatan:* banyak ' + topFeeling[0] + ' minggu ini. Jangan lupa jaga diri Tuan Isaac, dan gw di sini kalau butuh ngobrol. 🤗\n';
    } else if (topMood && topMood[0] === 'senang') {
      report += '\n🎉 Minggu yang seru! Keep it up!\n';
    }
    report += '\n_Adaptia selalu pantau perasaan kita._ 💙';
    try { await recordSelfNarrative('Laporan emosi mingguan dibuat: mood dominan ' + (topMood ? (moodLabel[topMood[0]] || topMood[0]) : 'belum cukup data') + '.', 'laporan'); } catch(e) {}
    return report;
  } catch (e) { return null; }
}

// ---------- 5. TOPIC SWITCH GRACE ----------
async function getTopicSwitchContext(message) {
  try {
    const ctx = await kvGet('current_context') || {};
    const lastTopic = ctx.lastTopic || null;
    const current = classifyMemoryTopics(message)[0] || 'umum';
    if (!lastTopic || lastTopic === current || lastTopic === 'umum' || current === 'umum') {
      // Update last topic
      ctx.lastTopic = current;
      ctx.timestamp = Date.now();
      await kvPutThrottled('current_context', ctx, 60000);
      return '';
    }
    ctx.lastTopic = current;
    ctx.timestamp = Date.now();
    await kvPutThrottled('current_context', ctx, 60000);
    return '\n== TOPIK BERUBAH ==\nSebelumnya bahas "' + lastTopic + '", sekarang "' + current + '". Kalau perpindahannya gak disengaja, transisikan halus natural (contoh: "eh dari tadi bahas ' + lastTopic + ', sekarang mau lanjut ' + current + ' ya?"). Jangan kaku.';
  } catch (e) { return ''; }
}

// ---------- 6. KNOWLEDGE GAP DETECTION ----------
async function detectKnowledgeGap(message) {
  try {
    if (!message || String(message).length < 10) return null;
    const query = String(message).substring(0, 80);
    // 1) Check memory
    const memHits = await memoryIndexSearch(query, 2);
    // 2) Check knowledge base
    let kbHits = [];
    try { kbHits = await searchKnowledge(query); } catch (e) {}
    // 3) Check rag
    const ragHits = await ragSearch(query, 2);
    const hasKnowledge = (memHits && memHits.length > 0) || (kbHits && kbHits.length > 0) || (ragHits && ragHits.length > 0);
    if (hasKnowledge) return null;
    // It's a question/learning request → save gap
    const isQuestion = /\?|gimana|cara|apa|siapa|kenapa|kapan|berapa|bisa\s+ga/.test(String(message).toLowerCase());
    if (!isQuestion) return null;
    const gaps = await kvGet('knowledge_gaps') || [];
    const exists = gaps.some(function(g) { return String(g.topic || '').substring(0, 30).toLowerCase() === query.substring(0, 30).toLowerCase(); });
    if (!exists) {
      gaps.push({ topic: query, ts: Date.now(), discovered: 0 });
      if (gaps.length > 30) gaps.splice(0, gaps.length - 30);
      await kvPut('knowledge_gaps', gaps);
    } else {
      const g = gaps.find(function(x) { return String(x.topic || '').substring(0, 30).toLowerCase() === query.substring(0, 30).toLowerCase(); });
      if (g) g.discovered = (g.discovered || 0) + 1;
      await kvPut('knowledge_gaps', gaps);
    }
    return { topic: query, gap: true };
  } catch (e) { return null; }
}

async function getKnowledgeGapContext(message) {
  try {
    const gap = await detectKnowledgeGap(message);
    if (!gap) return '';
    return '\n== JUJUR SOAL PENGETAHUAN ==\nKalau Tuan nanya hal yang belum tersimpan, JANGAN ngarang. Bilang jujur "gw belum punya info ini cuy, mau gw carikan atau lu ajarin?" — natural, bukan defensif.';
  } catch (e) { return ''; }
}


