async function getAreaRegistry(live) {
  try {
    const kv = await kvGet('area_registry');
    const reg = (kv && kv.otak) ? kv : JSON.parse(JSON.stringify(AREA_REGISTRY_DEFAULT));
    if (live === false) return reg;
    const skills = await kvGet('implemented_skills') || [];
    const custom = await kvGet('custom_skills') || [];
    const insights = await kvGet('mem_insights') || [];
    const ends = await kvGet('loose_ends') || [];
    const pers = await getPersona();
    const narr = await kvGet('self_narrative') || [];
    const idx = await kvGet('memory_index') || [];
    const ent = await kvGet('memory_entities') || [];
    const links = await kvGet('memory_links') || [];
    const stories = await kvGet('stories') || [];
    const corrections = await kvGet('corrections') || [];
    const moodTrend = await kvGet('mood_trend') || {};
    const mem = await getCloudMemory('default');
    reg.live = {
      otak: {
        komponen: reg.otak.length,
        skills: (Array.isArray(skills)?skills.length:0) + (Array.isArray(custom)?custom.length:0),
        memori: (Array.isArray(idx)?idx.length:0) + (Array.isArray(ent)?ent.length:0) + (Array.isArray(links)?links.length:0),
        insight: Array.isArray(insights)?insights.length:0,
        looseEnds: Array.isArray(ends)?ends.length:0,
        koreksi: Array.isArray(corrections)?corrections.length:0
      },
      tubuh: {
        komponen: reg.tubuh.length,
        story: Array.isArray(stories)?stories.length:0
      },
      jiwa: {
        komponen: reg.jiwa.length,
        innerVoice: (pers.innerVoice||[]).length,
        cerita: Array.isArray(narr)?narr.length:0,
        moodTrend: (moodTrend.history||[]).length
      },
      interaksi: mem.interactions || 0,
      ts: Date.now()
    };
    return reg;
  } catch(e) { return JSON.parse(JSON.stringify(AREA_REGISTRY_DEFAULT)); }
}
function classifyUpgradeArea(name, desc) {
  try {
    const t = String((name||'') + ' ' + (desc||'')).toLowerCase();
    const otakK = ['skill','memori','memory','insight','loose','koreksi','correction','model','ai','routing','learning','sinaps','decay','goal','reminder','knowledge','analisa','analisis','predict','prediksi','planning','logic','brain','otak','milestone','heal','repair','laporan','feedback','ringkasan','urgensi'];
    const tubuhK = ['ui','tampilan','border','avatar','bubble','tombol','button','icon','story viewer','voice','mic','tts','suara','gesture','swipe','keyboard','popup','panel','kategori','splash','welcome','chat area','header','background','font','animasi','transisi','ekspresi','video','gambar','input','story','skin'];
    const jiwaK = ['persona','mood','emosi','emotion','inner voice','innervoice','kepribadian','personality','nilai','principles','perasaan','feeling','identitas','cerita','narrative','sapaan','ketidakhadiran','absence','kangen','jiwa','soul','karakter','harapan','mimpi','impian'];
    let score = { otak:0, tubuh:0, jiwa:0 };
    otakK.forEach(function(k){ if(t.indexOf(k) >= 0) score.otak++; });
    tubuhK.forEach(function(k){ if(t.indexOf(k) >= 0) score.tubuh++; });
    jiwaK.forEach(function(k){ if(t.indexOf(k) >= 0) score.jiwa++; });
    if (score.otak >= score.tubuh && score.otak >= score.jiwa) return 'otak';
    if (score.tubuh >= score.jiwa) return 'tubuh';
    return 'jiwa';
  } catch(e) { return 'otak'; }
}
async function registerFeatureToArea(name, area, desc) {
  try {
    area = String(area||'').toLowerCase();
    if (!['otak','tubuh','jiwa'].includes(area)) area = classifyUpgradeArea(name, desc);
    if (!name) return false;
    const reg = await getAreaRegistry(false);
    const list = Array.isArray(reg[area]) ? reg[area] : [];
    const entry = { name: String(name).substring(0,60), sub: String(desc||'').substring(0,120), icon: area==='otak' ? '\u{1F9E0}' : area==='tubuh' ? '\u{1FAC0}' : '\u{1F49B}' };
    const exists = list.findIndex(function(x){ return x.name === entry.name; });
    if (exists >= 0) list[exists] = entry; else list.push(entry);
    reg[area] = list.slice(0, 60);
    reg.updated = new Date().toISOString();
    await kvPutThrottled('area_registry', reg, 60000);
    return true;
  } catch(e) { return false; }
}
