// === CONVERSATION INTELLIGENCE ===
if(path==='/api/conversation-intelligence'&&method==='GET'){
  const history = await kvGet('chat_history') || [];
  const today = new Date().toISOString().split('T')[0];
  const thisWeek = new Date(Date.now() - 7*86400000).toISOString().split('T')[0];
  const todayChats = history.filter(h => new Date(h.ts).toISOString().split('T')[0] === today);
  const weekChats = history.filter(h => h.ts >= thisWeek);
  const avgLen = history.length > 0 ? Math.round(history.reduce((a,h) => a + (h.message||'').length, 0) / history.length) : 0;
  const topics = {};
  history.forEach(h => {
    const words = (h.message||'').toLowerCase().split(/\s+/);
    words.forEach(w => { if(w.length > 4) topics[w] = (topics[w]||0) + 1; });
  });
  const topTopics = Object.entries(topics).sort((a,b) => b[1]-a[1]).slice(0,10);
  return new Response(JSON.stringify({
    totalChats: history.length,
    todayChats: todayChats.length,
    weekChats: weekChats.length,
    avgMessageLength: avgLen,
    topTopics: topTopics.map(([t,c]) => ({topic:t,count:c})),
    engagementLevel: history.length > 100 ? 'high' : history.length > 30 ? 'medium' : 'low'
  }),{headers:{'Content-Type':'application/json',...CORS}});
}

// === ACHIEVEMENT SYSTEM ===
if(path==='/api/achievements'&&method==='GET'){
  const mem = await getCloudMemory('default');
  const identity = await getIdentity();
  const history = await kvGet('chat_history') || [];
  const achievements = [];
  // Chat milestones
  if(history.length >= 10) achievements.push({id:'chat_10',name:'Chatterbox',desc:'10 chats',icon:'💬'});
  if(history.length >= 50) achievements.push({id:'chat_50',name:'Talker',desc:'50 chats',icon:'🗣️'});
  if(history.length >= 100) achievements.push({id:'chat_100',name:'Century Club',desc:'100 chats',icon:'💯'});
  if(history.length >= 500) achievements.push({id:'chat_500',name:'Legend',desc:'500 chats',icon:'🏆'});
  // Goal milestones
  const doneGoals = (mem.goals||[]).filter(g=>g.done);
  if(doneGoals.length >= 1) achievements.push({id:'goal_1',name:'Starter',desc:'1 goal done',icon:'🎯'});
  if(doneGoals.length >= 5) achievements.push({id:'goal_5',name:'Achiever',desc:'5 goals done',icon:'⭐'});
  if(doneGoals.length >= 10) achievements.push({id:'goal_10',name:'Goal Master',desc:'10 goals done',icon:'🏅'});
  // Time-based
  const hour = new Date().getHours();
  if(hour >= 0 && hour < 5) achievements.push({id:'night_owl',name:'Night Owl',desc:'Chat di atas jam 12',icon:'🦉'});
  if(hour >= 5 && hour < 7) achievements.push({id:'early_bird',name:'Early Bird',desc:'Chat sebelum jam 7',icon:'🐦'});
  // Fact milestones
  if((mem.facts||[]).length >= 20) achievements.push({id:'facts_20',name:'Knowledgeable',desc:'20 facts learned',icon:'📚'});
  if((mem.facts||[]).length >= 50) achievements.push({id:'facts_50',name:'Encyclopedia',desc:'50 facts learned',icon:'🎓'});
  // User level
  let level = 'Beginner';
  const score = history.length + (mem.facts||[]).length * 2 + doneGoals.length * 5;
  if(score >= 200) level = 'Legend';
  else if(score >= 100) level = 'Master';
  else if(score >= 50) level = 'Pro';
  else if(score >= 20) level = 'Regular';
  return new Response(JSON.stringify({achievements,level,totalScore:score,count:achievements.length}),{headers:{'Content-Type':'application/json',...CORS}});
}

