// === MEMORY NETWORK ===
if(path==='/api/memory/network'&&method==='GET'){
  const mem = await getCloudMemory('default');
  const facts = mem.facts || [];
  const connections = [];
  // Find related facts
  for(let i=0; i<facts.length; i++){
    for(let j=i+1; j<facts.length; j++){
      const words1 = facts[i].toLowerCase().split(/\s+/);
      const words2 = facts[j].toLowerCase().split(/\s+/);
      const common = words1.filter(w => words2.includes(w) && w.length > 4);
      if(common.length > 0) connections.push({from:facts[i].substring(0,50),to:facts[j].substring(0,50),shared:common.length});
    }
  }
  connections.sort((a,b)=>b.shared-a.shared);
  return new Response(JSON.stringify({
    totalFacts: facts.length,
    connections: connections.slice(0,20),
    networkStrength: Math.min(100, connections.length * 2)
  }),{headers:{'Content-Type':'application/json',...CORS}});
}

