// === SMART GOALS ===
if(path==='/api/goals/smart'&&method==='GET'){
  const mem = await getCloudMemory('default');
  const history = await kvGet('chat_history') || [];
  const goals = (mem.goals||[]).filter(g => g && g.text && g.text.length > 1);
  const active = goals.filter(g => !g.done);
  const done = goals.filter(g => g.done);
  // Analyze patterns for suggestions
  const suggestions = [];
  const topics = {};
  history.slice(-20).forEach(h => {
    const words = (h.message||'').toLowerCase().split(/\s+/);
    words.filter(w=>w.length>4).forEach(w => topics[w]=(topics[w]||0)+1);
  });
  const topTopic = Object.entries(topics).sort((a,b)=>b[1]-a[1])[0];
  if(topTopic && !active.find(g=>g.text.toLowerCase().includes(topTopic[0]))){
    suggestions.push({text:'Fokus ke topik: '+topTopic[0], priority:'medium', reason:'Topik paling sering dibahas'});
  }
  if(active.length === 0 && done.length > 0){
    suggestions.push({text:'Bikin goal baru!', priority:'high', reason:'Semua goal udah selesai'});
  }
  if(active.length > 5){
    suggestions.push({text:'Prioritasin goal', priority:'high', reason:'Terlalu banyak goal aktif'});
  }
  // Time-based suggestions
  const hour = new Date().getHours();
  if(hour >= 20) suggestions.push({text:'Rehat dulu, lanjut besok', priority:'low',reason:'Udah malam'});
  return new Response(JSON.stringify({active,done,suggestions,totalGoals:goals.length,completionRate:goals.length>0?Math.round(done.length/goals.length*100):0}),{headers:{'Content-Type':'application/json',...CORS}});
}

// === DEEP LEARNING ===
if(path==='/api/learning/deep'&&method==='GET'){
  const mem = await getCloudMemory('default');
  const history = await kvGet('chat_history') || [];
  const facts = mem.facts || [];
  // Analyze user expertise
  const expertiseMap = {};
  const expertiseKeywords = {
    'beginner': ['baru','gimana','cara','apa itu','gabisa','bingung'],
    'intermediate': ['kenapa','error','bug','fix','optimize','improve'],
    'advanced': ['architecture','pattern','refactor','scale','performance','security']
  };
  history.forEach(h => {
    const msg = (h.message||'').toLowerCase();
    Object.entries(expertiseKeywords).forEach(([level, kws]) => {
      if(kws.some(k => msg.includes(k))) expertiseMap[level] = (expertiseMap[level]||0)+1;
    });
  });
  const dominantLevel = Object.entries(expertiseMap).sort((a,b)=>b[1]-a[1])[0];
  // Knowledge gaps
  const knownTopics = facts.filter(f=>f.startsWith('Topik aktif:')).map(f=>f.replace('Topik aktif: ',''));
  const suggestedTopics = ['testing','deployment','security','performance','documentation','refactoring'].filter(t=>!knownTopics.includes(t));
  return new Response(JSON.stringify({
    expertiseLevel: dominantLevel ? dominantLevel[0] : 'unknown',
    expertiseScores: expertiseMap,
    knownTopics,
    suggestedTopics: suggestedTopics.slice(0,3),
    totalKnowledge: facts.length,
    learningRate: Math.round(facts.length / Math.max(1, history.length) * 100)
  }),{headers:{'Content-Type':'application/json',...CORS}});
}

