// === MEMORY SEARCH ADVANCED ===
if(path==='/api/memory/search'&&method==='GET'){
  const q = new URL(request.url).searchParams.get('q') || '';
  if(!q) return new Response(JSON.stringify({error:'No query'}),{status:400,headers:{'Content-Type':'application/json',...CORS}});
  const mem = await getCloudMemory('default');
  const facts = mem.facts || [];
  const queryWords = q.toLowerCase().split(/\s+/).filter(w=>w.length>2);
  // Fuzzy matching
  const results = facts.map(f => {
    const fLower = f.toLowerCase();
    let score = 0;
    queryWords.forEach(w => {
      if(fLower.includes(w)) score += 10;
      // Partial match
      for(let i=0; i<fLower.length-w.length; i++){
        const substr = fLower.substring(i,i+w.length);
        let matches = 0;
        for(let j=0; j<w.length; j++){
          if(w[j] === substr[j]) matches++;
        }
        score += matches / w.length * 3;
      }
    });
    return {fact:f.substring(0,150),score:Math.round(score),confidence:Math.min(100,Math.round(score*10))};
  }).filter(r=>r.score>0).sort((a,b)=>b.score-a.score).slice(0,10);
  // Related memories
  const related = results.length > 0 ? facts.filter(f => {
    const common = queryWords.filter(w => f.toLowerCase().includes(w));
    return common.length > 0 && !results.find(r => r.fact === f.substring(0,150));
  }).slice(0,3).map(f=>f.substring(0,100)) : [];
  return new Response(JSON.stringify({query:q,results,related,totalFacts:facts.length}),{headers:{'Content-Type':'application/json',...CORS}});
}

