// === LEARN FROM CHAT (WhatsApp/Telegram/etc) ===
if(path==='/api/learn-chat'&&method==='POST'){
  try{
    const body = await request.json();
    const chatText = body.chat || body.text || '';
    const source = body.source || 'unknown';
    if(!chatText || chatText.length < 20) return new Response(JSON.stringify({error:'Chat too short, min 20 chars'}),{status:400,headers:{'Content-Type':'application/json',...CORS}});
    
    const extracted = [];
    const lines = chatText.split('\n').filter(l=>l.trim().length > 5);
    
    for(const line of lines){
      const l = line.trim();
      // Extract names mentioned
      const nameMatch = l.match(/^[\w\s]+[:|]/);
      if(nameMatch) {
        const name = nameMatch[0].replace(/[:|]/g,'').trim();
        if(name.length > 2 && name.length < 30) extracted.push('Nama di chat: ' + name);
      }
      // Extract topics
      const topicWords = ['game','code','bug','project','deadline','meeting','client','deploy','update','design','deploy','server','app','website','android','ios','flutter','react','godot','mugen','fighting','bug','fix','error'];
      for(const t of topicWords){
        if(l.toLowerCase().includes(t)) extracted.push('Topik chat: ' + t);
      }
      // Extract emotions/sentiment
      if(l.match(/(bagus|keren|mantap|joss|asik|senang|happy|suka|best|top|gokil)/i)) extracted.push('Sentimen positif: ' + l.substring(0,80));
      if(l.match(/(jelek|rugi|benci|galau|sedih|marah|stress|bosan|capek|gagal|error)/i)) extracted.push('Sentimen negatif: ' + l.substring(0,80));
      // Extract decisions
      if(l.match(/(pilih|decide|pakai|guna|tetapkan|okay|oke|siap|gas|go)/i)) extracted.push('Keputusan: ' + l.substring(0,100));
      // Extract questions
      if(l.includes('?')) extracted.push('Pertanyaan: ' + l.substring(0,100));
      // Extract actions
      if(l.match(/(udah|done|selesai|finish|submit|kirim|upload|deploy|push)/i)) extracted.push('Aksi: ' + l.substring(0,100));
      // Extract slang/informal patterns
      const slangMatch = l.match(/\b(gw|lu|gue|lo|cuy|bro|bg|anjay|mantap|woi|hei|wkwk|haha|lol|teh|bang|sis)\b/gi);
      if(slangMatch) extracted.push('Slang detected: ' + [...new Set(slangMatch)].join(', '));
    }
    
    // Deduplicate
    const unique = [...new Set(extracted)].slice(0, 50);
    
    // Save to memory
    const mem = await getCloudMemory('default');
    if(!mem.facts) mem.facts = [];
    let added = 0;
    for(const fact of unique){
      const factStr = '['+source+'] ' + fact;
      if(!mem.facts.includes(factStr) && fact.length > 5){
        mem.facts.push(factStr);
        added++;
      }
    }
    // Keep max 100 facts
    if(mem.facts.length > 100) mem.facts = mem.facts.slice(-100);
    await saveCloudMemory('default', mem);
    
    // Generate summary
    const topics = unique.filter(f=>f.startsWith('Topik'));
    const names = unique.filter(f=>f.startsWith('Nama'));
    const sentiments = unique.filter(f=>f.startsWith('Sentimen'));
    
    return new Response(JSON.stringify({
      status:'ok',
      source,
      linesProcessed: lines.length,
      factsExtracted: unique.length,
      factsSaved: added,
      totalFacts: mem.facts.length,
      summary: {
        topics: topics.map(t=>t.replace('Topik chat: ','')),
        names: names.map(n=>n.replace('Nama di chat: ','')),
        sentiments: sentiments.length,
        preview: unique.slice(0,5)
      }
    }),{headers:{'Content-Type':'application/json',...CORS}});
  }catch(e){ return new Response(JSON.stringify({error:e.message}),{status:500,headers:{'Content-Type':'application/json',...CORS}}); }
}

// === LEARN FROM EXPORTED CHAT (WhatsApp Export) ===
if(path==='/api/learn-export'&&method==='POST'){
  try{
    const body = await request.json();
    const chatText = body.chat || body.text || '';
    const source = body.source || 'whatsapp-export';
    const groupName = body.groupName || 'Unknown Group';
    if(!chatText || chatText.length < 50) return new Response(JSON.stringify({error:'Chat too short, min 50 chars'}),{status:400,headers:{'Content-Type':'application/json',...CORS}});
    
    const extracted = [];
    const lines = chatText.split('\n').filter(l=>l.trim().length > 3);
    
    // WhatsApp export format: "DD/MM/YYYY, HH:MM - Name: Message"
    // or "MM/DD/YY, HH:MM AM/PM - Name: Message"
    const waPattern = /^(\d{1,2}\/\d{1,2}\/\d{2,4}),?\s*(\d{1,2}:\d{2}(?:\s*[APap][Mm])?)\s*[-–]\s*([^:]+):\s*(.*)/;
    
    const participants = {};
    const messages = [];
    let mediaCount = 0;
    let links = [];
    
    for(const line of lines){
      const match = line.match(waPattern);
      if(match){
        const [, date, time, name, msg] = match;
        const trimmedName = name.trim();
        const trimmedMsg = msg.trim();
        
        // Track participants
        if(!participants[trimmedName]) participants[trimmedName] = 0;
        participants[trimmedName]++;
        
        // Track messages
        messages.push({name:trimmedName, msg:trimmedMsg, date, time});
        
        // Detect media
        if(trimmedMsg.match(/<[^>]*omitted>|media omitted|file omitted|image omitted|video omitted|audio omitted|sticker omitted|document omitted|GIF omitted/i)){
          mediaCount++;
          continue;
        }
        
        // Detect links
        const urlMatch = trimmedMsg.match(/https?:\/\/[^\s]+/g);
        if(urlMatch) links.push(...urlMatch);
        
        // Skip empty/system messages
        if(!trimmedMsg || trimmedMsg.length < 2) continue;
        
        // === EXTRACT FACTS ===
        
        // Topics
        const topicWords = ['game','code','bug','project','deadline','meeting','client','deploy','update','design','server','app','website','android','ios','flutter','react','godot','mugen','fighting','fix','error','server','database','api','frontend','backend','ui','ux','deploy','release','update','push','commit','merge','branch','test','review','feedback','schedule','agenda','reminder','task','todo','progress','report','report','result','data','analytics','marketing','sales','customer','user','feature','improvement','suggestion','idea','plan','strategy','budget','cost','price','payment','invoice','bill','receipt','transaction','account','profile','setting','config','setup','install','update','upgrade','downgrade','subscription','plan','pricing','offer','discount','promo','campaign','launch','release','announce','news','update','changelog','version','release','hotfix','patch','hotpatch','hotfix','hotpatch'];
        for(const t of topicWords){
          if(trimmedMsg.toLowerCase().includes(t)) extracted.push('['+groupName+'] Topik: ' + t);
        }
        
        // People interactions
        const mentionMatch = trimmedMsg.match(/@(\w+)/g);
        if(mentionMatch) extracted.push('['+groupName+'] Mention: ' + mentionMatch.join(', '));
        
        // Emotions
        if(trimmedMsg.match(/(bagus|keren|mantap|joss|asik|senang|happy|suka|best|top|gokil|anjay|love|❤️|😍|🔥|💯)/i)) extracted.push('['+groupName+'] Sentimen positif dari ' + trimmedName);
        if(trimmedMsg.match(/(jelek|rugi|benci|galau|sedih|marah|stress|bosan|capek|gagal|error|broken|bug|crash|fail)/i)) extracted.push('['+groupName+'] Sentimen negatif dari ' + trimmedName);
        
        // Questions
        if(trimmedMsg.includes('?')) extracted.push('['+groupName+'] Pertanyaan: ' + trimmedMsg.substring(0,100));
        
        // Decisions
        if(trimmedMsg.match(/^(oke|ok|siap|gas|go|agree|setuju|bener|betul|yes|y|ya|yoi|mantap|gas aja)/i)) extracted.push('['+groupName+'] Keputusan dari ' + trimmedName + ': ' + trimmedMsg.substring(0,50));
        
        // Plans/schedules
        if(trimmedMsg.match(/(jadwal|schedule|meeting|deadline|hari|jam|besok|lusa|minggu|bulan)/i)) extracted.push('['+groupName+'] Jadwal: ' + trimmedMsg.substring(0,100));
        
        // Problems
        if(trimmedMsg.match(/(error|bug|crash|gagal|rusak|problem|issue|masalah|trouble)/i)) extracted.push('['+groupName+'] Masalah: ' + trimmedMsg.substring(0,100));
        
        // Solutions
        if(trimmedMsg.match(/(fix|solusi|cara|tips|saran|rekomendasi|solution|workaround)/i)) extracted.push('['+groupName+'] Solusi: ' + trimmedMsg.substring(0,100));
        
      } else {
        // Non-standard format, try to extract as plain text
        if(line.length > 10) extracted.push('['+groupName+'] Chat: ' + line.substring(0,100));
      }
    }
    
    // Deduplicate
    const unique = [...new Set(extracted)].slice(0, 100);
    
    // Save to memory
    const mem = await getCloudMemory('default');
    if(!mem.facts) mem.facts = [];
    let added = 0;
    for(const fact of unique){
      if(!mem.facts.includes(fact) && fact.length > 10){
        mem.facts.push(fact);
        added++;
      }
    }
    if(mem.facts.length > 100) mem.facts = mem.facts.slice(-100);
    await saveCloudMemory('default', mem);
    
    // Save group info
    const groupInfo = {
      name: groupName,
      participants: Object.keys(participants),
      totalMessages: messages.length,
      mediaCount,
      links: links.slice(0,10),
      exportedAt: new Date().toISOString()
    };
    await kvPut('group_'+groupName.replace(/\s+/g,'_'), groupInfo);
    
    return new Response(JSON.stringify({
      status:'ok',
      source,
      groupName,
      linesProcessed: lines.length,
      messagesParsed: messages.length,
      participants: Object.entries(participants).map(([name,count])=>({name,count})),
      factsExtracted: unique.length,
      factsSaved: added,
      totalFacts: mem.facts.length,
      mediaCount,
      linksFound: links.length,
      summary: unique.slice(0,10)
    }),{headers:{'Content-Type':'application/json',...CORS}});
  }catch(e){ return new Response(JSON.stringify({error:e.message}),{status:500,headers:{'Content-Type':'application/json',...CORS}}); }
}

